// Do not edit manually - regenerate with scripts/generate-book-data
//
// Shape: bookGrammar[bookId][difficulty] = GrammarNote[][]
//   - Outer array: one entry per book "part" (chapter-like split).
//   - Single-part books are still wrapped as [notes] for uniformity.

export interface GrammarNote {
  pattern: string;
  meaning: string;
  example: string;
  jlpt: string;
  tip: string;
}

export const bookGrammar: Record<string, Record<string, GrammarNote[][]>> = {"a-aki":{"simplified":[[{"example":"たくさん書いてありました","tip":"Used with transitive verbs to focus on the result of someone's action rather than who did it.","meaning":"Indicates a state that remains as the result of a conscious action.","pattern":"～てある / ～てあります","jlpt":"N5"},{"pattern":"～と (conditional)","tip":"Use this for natural laws, machines (pushing buttons), or fixed sequences of events.","meaning":"When A occurs, B naturally or inevitably follows.","example":"秋になると","jlpt":"N5"},{"pattern":"～そうです (hearsay)","meaning":"Indicates that the information was heard or read from another source (hearsay).","tip":"Unlike 'looks like' (sou desu), the hearsay version always follows the dictionary form (plain form).","example":"透けて見えるそうです","jlpt":"N4"},{"tip":"Using 'ni omou' often suggests an emotional reaction or a subjective perspective.","meaning":"To feel or think a certain way instinctively.","example":"可哀想に思いました","pattern":"～に思う / ～とおもう","jlpt":"N4"},{"jlpt":"N3","meaning":"While a certain state or condition continues.","tip":"Often implies that if you don't do it now, the chance will disappear (e.g., while it's still summer).","example":"夏のうちはにできています","pattern":"～うちに"},{"jlpt":"N4","pattern":"～よう (Volitional form)","example":"夏休みに海へ行こう","tip":"With Group 2 verbs (ru-verbs), replace 'ru' with 'you'. With Group 1 (u-verbs), change the 'u' sound to 'o' and add 'u'.","meaning":"The 'let's' form, used to express intent or an invitation."},{"example":"話しているのを見ると","tip":"Use 'no' instead of 'koto' when the following verb involves direct perception like seeing, hearing, or waiting.","meaning":"Normalizing a verb to turn an action into a noun/object.","pattern":"～の (Nominalizer)","jlpt":"N4"},{"jlpt":"N3","pattern":"～ようです","example":"書いたようです","tip":"It suggests a logical guess based on evidence, similar to 'it seems that' or 'it looks as if'.","meaning":"Expresses a conjecture or appearance based on what the speaker has observed."}]],"intermediate":[[{"example":"詩材の準備をしておくのである。","pattern":"～ておく","tip":"Focus on the preparation aspect; it means doing something now so you are ready for later.","meaning":"To do something in advance or for future use.","jlpt":"N4"},{"tip":"For verbs, change the final 'u' sound to 'e' and add 'ba'. It often expresses a logical result.","meaning":"Conditional \"if\" or \"when\".","jlpt":"N4","example":"「秋について」という注文が来れば","pattern":"～ば"},{"meaning":"It seems that... / I heard that... (indicating an inference based on evidence).","tip":"Use this when you have some basis for your guess but aren't 100% certain.","jlpt":"N4","pattern":"～らしい","example":"精神だけがふらふら飛んでいる様子を指して言っているらしい。"},{"tip":"It is used to describe the degree of a state or emotion by providing an example.","meaning":"To the extent that... / So much so that...","jlpt":"N3","example":"私は胸が焼け焦げるほどに、そのみじめな女を恋した。","pattern":"～ほど"},{"pattern":"～と (conditional)","example":"耳を澄まして注意していると","jlpt":"N4","meaning":"When/if (followed by a natural or inevitable consequence).","tip":"In this context, it marks the discovery of something that happens naturally when you take an action."},{"meaning":"Despite / Although / Even though (often used at the end of a sentence to show regret or frustration).","tip":"When it ends a sentence, it often implies \"I wish it weren't so\" or \"despite the situation.\"","jlpt":"N3","pattern":"～のに","example":"もう秋が夏と一緒に忍び込んで来ているのに。"},{"pattern":"～ともなれば","example":"本職の詩人ともなれば、いつどんな注文があるかわからない。","jlpt":"N1","meaning":"When it comes to being... / If someone becomes a... (emphasizes a special status or rank).","tip":"This is used for high-level positions or significant situations where expectations naturally change."}]],"original":[[{"meaning":"to do something in advance for future use or to leave something in a certain state.","tip":"In speech, this often contracts: ～ておく becomes ～とく.","jlpt":"N4","pattern":"～ておく (～て置く)","example":"準備をして置くのである。"},{"meaning":"indicates a guess based on observation or information; 'it seems like' or 'apparently'.","jlpt":"N4","tip":"Unlike 'yoda', 'rashii' is used when you have some objective basis or rumors for your conclusion.","pattern":"～らしい","example":"精神だけがふらふら飛んでいる様子を指して言っている言葉らしい。"},{"pattern":"～ぬ (～ず)","example":"それを見破ることが出来ぬ。","meaning":"A literary or formal negative form of a verb, equivalent to ～ない.","tip":"You will see this often in literature or proverbs. 'Surnu' becomes 'senu' and 'kuru' becomes 'konu'.","jlpt":"N3"},{"meaning":"emphasizes that once a certain high level or special status is reached, things naturally change or become serious.","tip":"Used for roles, occupations, or special occasions to show a higher standard of expectation.","jlpt":"N1","pattern":"～ともなれば / ～ともなると","example":"本職の詩人ともなれば、いつどんな注文があるか..."},{"pattern":"～ほど (～ほどに)","example":"胸が焼き焦げるほどにそのみじめな女を恋した。","meaning":"indicates the degree or extent of an action or state; 'to the extent that...'.","jlpt":"N3","tip":"Use this to add drama or emphasis to your descriptions by comparing them to an extreme limit."},{"meaning":"indicates an expectation or belief that something should be/have been a certain way, often followed by regret or surprise when it isn't.","jlpt":"N3","tip":"If followed by 'noni', it strongly implies that the reality is the opposite of the expectation.","pattern":"～はず (～筈)","example":"弱者の友であった筈なのに。"},{"meaning":"A formal/literary way to express reason or cause; 'because' or 'due to'.","tip":"This is very stiff and formal. In modern conversation, you would use 'node' or 'kara'. Shortened to 'yue' in some expressions.","jlpt":"N2","pattern":"～がゆえに (～が故に)","example":"並ハズレテ、タクマシキガ故ニ、死ナズ在リヌル。决シテ、ハカナキ態ニハ非ズ。と書かれてある。"}]]},"kumo-no-ito":{"simplified":[[{"example":"いいにおいがしていました。","meaning":"Used to describe an ongoing state or action in the past.","jlpt":"N5","tip":"Think of it as the past tense version of 'doing something' or 'being in a state'.","pattern":"～ていました"},{"example":"悪いことをたくさんしました。","jlpt":"N5","meaning":"nominalizes verbs or adjectives to mean 'thing(s)', 'action', or 'fact'.","tip":"Use this when you want to turn a simple action into a 'topic' or a 'thing' you can talk about.","pattern":"～こと"},{"jlpt":"N5","meaning":"Used to express having the experience of doing something.","tip":"Always use the past tense (Ta-form) before this phrase. It's for general life experiences, not things you did just today.","pattern":"～たことがあります","example":"いいことをしたことがあります。"},{"jlpt":"N4","meaning":"Used to define or name something ('A called B').","pattern":"～という","tip":"This is essential for introducing people, books, or places by their names. Kind of like saying \"The guy named Kandata.\"","example":"犍陀多という男"},{"tip":"This uses the volitional form (let's form). It often implies that you tried but didn't actually complete the action.","pattern":"～ようとする","meaning":"To try to do something, or to be about to do something.","jlpt":"N4","example":"踏もうとしましたが"},{"meaning":"Expresses a strong expectation or belief based on logic. 'Should be' or 'it must be'.","jlpt":"N3","pattern":"～はずだ","tip":"Use this when you are 99% sure about something based on evidence or the nature of things.","example":"生きたいと思っているはずだ"},{"example":"地獄から助けようと思いました。","jlpt":"N4","meaning":"Used to express the speaker's intention or decision to do something.","pattern":"～よう（意向形）と思う","tip":"Use the volitional form + と思う to talk about what you are planning/thinking of doing."}],[{"example":"地獄の暗い中にいました。","jlpt":"N5","meaning":"State of being/existence (for animate subjects)","tip":"Use 'いる' for people and animals, and 'ある' for inanimate objects.","pattern":"～にいる (いました)"},{"example":"下りてきていました。","meaning":"Ongoing action in the past (progressive)","jlpt":"N5","tip":"Think of this as the past tense version of '～ている' (is doing).","pattern":"～ていた (ていました)"},{"tip":"For verbs, change the final 'u' sound to 'e' and add 'ba'. It focuses on the condition needed for a result.","pattern":"～ば","example":"登れば極楽へ行けるかもしれない！","meaning":"Conditional \"if\" (Provisional form)","jlpt":"N4"},{"example":"極楽へ行けるかもしれない！","jlpt":"N4","meaning":"Indicates possibility or \"might/maybe\"","tip":"Use this when you are about 50% sure or less. It follows the plain form of verbs and adjectives.","pattern":"～かもしれない"},{"example":"疲れたので、少し休みました。","meaning":"Giving a reason (since/because)","jlpt":"N4","tip":"'Node' sounds more objective and polite than 'kara'. It is often used when explaining a situation or making an excuse.","pattern":"～ので"},{"example":"もう少しで出られるかもしれない","meaning":"Potential form (can do/be able to do)","jlpt":"N4","pattern":"～られる (Potential) vocalic/Ichidan","tip":"For Ichidan verbs (like deru), replace 'ru' with 'rare-ru'. In casual speech, the 'ra' is often dropped (dereru)."}],[{"meaning":"Explains a situation or gives a reason by adding an explanatory tone.","jlpt":"N4","pattern":"～のだ / ～のです / ～んです","tip":"Use this when explaining 'why' something happened or providing a background realization.","example":"登っていたのです"},{"example":"ついてきていました","pattern":"～てくる / ～てきました","tip":"Imagine the movement coming toward the narrator's point of view.","jlpt":"N4","meaning":"Indicates an action that comes toward the speaker or a continuous movement from the past to the present."},{"jlpt":"N4","meaning":"Indicates that when action A occurs, action B (often unexpected) is discovered.","pattern":"～（辞書形）＋と","tip":"This 'to' is like a factual trigger: 'Once X happens, Y naturally follows or is seen.'","example":"気がつくと"},{"jlpt":"N4","meaning":"Expresses completion of an action, often with a sense of regret or unintentional outcome.","tip":"In this context, it emphasizes the fear of an irreversible and negative result (the thread breaking).","pattern":"～てしまう / ～ちゃう","example":"糸が切れてしまう！"},{"jlpt":"N4","meaning":"Indicates a change in state or becoming a certain way.","pattern":"い形容詞（～く）＋なる / な形容詞（～に）＋なる","tip":"Drop the 'i' from adjectives and add 'ku' before 'naru' to show a shift in feeling or condition.","example":"怖くなりました"},{"tip":"Combined with 'Ore' (a rough male pronoun), it shows a strong, selfish claim to ownership.","pattern":"Noun + のもの","jlpt":"N5","meaning":"Indicates possession (mine). 'Mono' refers to a physical thing/object.","example":"俺のものだ！"}],[{"example":"銀色の糸だけが、まだ上から下がっていました。","pattern":"～ている / ～ていた","tip":"Use it for ongoing actions (is doing) or states resulting from an action (is hanging/has flowered).","meaning":"indicates continuity of an action or a state.","jlpt":"N5"},{"tip":"Unlike 'shika', 'dake' is used with positive verbs to emphasize that something is the exclusive focus.","pattern":"～だけ","example":"自分だけ助かろうとしました。","meaning":"only; just (indicates a limit).","jlpt":"N5"},{"meaning":"looks like; appears to be (based on visual impression).","jlpt":"N4","example":"とても悲しそうなかおをしました。","pattern":"～そう（な）","tip":"When attached to an adjective, drop the final 'i' or 'na'. It describes your observation of someone's feelings or appearance."},{"jlpt":"N4","meaning":"to try to; to attempt to do something.","example":"自分だけ助かろうとしました。","tip":"This represents an attempt or the moment someone is about to start an action. Often used when the attempt fails.","pattern":"Volitional Form + とした (とする)"},{"meaning":"indicates completion of an action, often with a sense of regret or accidental outcome.","jlpt":"N4","example":"それが糸を切ってしまったのです。","tip":"In this story, it emphasizes the unfortunate and irreversible nature of the thread breaking.","pattern":"～てしまう / ～てしまった"},{"example":"それが糸を切ってしまったのです。","tip":"Use this when you want to explain the \"why\" or \"how\" behind a situation to the listener.","pattern":"～のだ / ～のです / ～んです","meaning":"used for explanation, emphasis, or providing a reason.","jlpt":"N4"}]],"intermediate":[[{"tip":"Think of it as the past version of '～ています' (is doing). It sets the scene in storytelling.","meaning":"Indicates an action in progress or a state in the past. (Past continuous)","example":"歩いていました","jlpt":"N5","pattern":"～ていました"},{"meaning":"To try to do something, or to be about to do something.","jlpt":"N4","example":"踏み潰そうとしましたが","pattern":"Volitional form + と（する/した）","tip":"Use the 'Let's' form of the verb plus 'to suru'. It often implies the attempt didn't result in success."},{"example":"生きたいと思っているはずだ","jlpt":"N4","meaning":"Expresses a strong belief or expectation that something is true. (Surely...)","pattern":"～はずだ","tip":"Use this when you have a logical reason to believe something will happen or is the case."},{"tip":"Be careful! In modern Japanese, avoid using this for people unless you want to sound very informal or aggressive. '～てあげる' is safer.","pattern":"～てやる","meaning":"To do something for someone of lower status (or animals/plants). It can sound slightly rough or superior.","example":"蜘蛛を助けてやったのです","jlpt":"N4"},{"tip":"It often combines with 'ienai' (cannot say) to mean 'exquisite' or 'beyond words'.","meaning":"Indescribable; cannot say what/how (usually for emphasis).","example":"何とも言えないよい香り","jlpt":"N3","pattern":"何とも～ない"},{"tip":"This is used to express a plan or a thought process that is currently happening in the speaker's (or subject's) mind.","jlpt":"N3","example":"地獄から救い出してやろうと考えました","meaning":"To think of doing something; to intend to do something.","pattern":"Volitional form + と考える/と思う"},{"tip":"Derived from 'me' (eye) and 'kakeru'. It implies moving toward a specific target with strong intent.","meaning":"Aiming at; toward; in the direction of.","jlpt":"N1","example":"地獄の底めがけて","pattern":"～をめがけて"}],[{"pattern":"～と一緒に","jlpt":"N5","tip":"'Issho' means 'together'. The 'ni' marks the destination of the action of being together.","example":"罪人たちと一緒に","meaning":"Together with / along with (a person or group)"},{"tip":"Use this for actions that take time to complete, not for instantaneous actions.","example":"よじ登り始めました","meaning":"To start doing something (attached to the verb stem)","pattern":"Verb stem + 始める","jlpt":"N4"},{"example":"光りながら","tip":"The main action comes after 'nagara'. For example, in 'eating while walking', 'walking' is the secondary action.","meaning":"While doing (two actions happening simultaneously)","pattern":"Verb stem + ながら","jlpt":"N4"},{"meaning":"Might; perhaps; probably (indicates a possibility)","tip":"This can be used after nouns, adjectives, or plain form verbs. In casual speech, it is often shortened to 'kamo'.","example":"行けるかもしれない","jlpt":"N4","pattern":"～かもしれない"},{"pattern":"～ば","jlpt":"N3","tip":"For verbs, change the final 'u' sound to an 'e' sound and add 'ba'. It is often used for general truths or logical consequences.","example":"登り続ければ","meaning":"Conditional 'if' (Provisional form)"},{"meaning":"To come to; to gradually start to (indicates an action or change coming toward the present)","tip":"In this context, it shows the physical motion toward the speaker or a psychological change reaching a certain point.","example":"かなり高くまで登ってきたこと","jlpt":"N3","pattern":"Verb (Te-form) + くる"},{"pattern":"～ではないか / ではありませんか","jlpt":"N2","example":"降りてきているではありませんか","tip":"In literature, this rhetorical question is used to emphasize a sudden realization or an unexpected sight.","meaning":"Isn't it...?; Behold! (Expressing surprise or highlighting a discovery)"}],[{"tip":"In this context, it describes the physical motion of moving further away from the starting point up the thread.","pattern":"～ていく (te-iku)","meaning":"to go away from the speaker / to continue doing into the future","example":"糸を登っていくのを見て","jlpt":"N5"},{"pattern":"～かもしれない (kamoshirenai)","tip":"Often used to express worries or uncertainties. It follows the plain form of verbs and adjectives.","jlpt":"N4","meaning":"might; perhaps; indicates a possibility of something happening","example":"細い糸が切れてしまうかもしれない"},{"pattern":"～のに (noni)","tip":"It connects two contrasting ideas. In this story, it emphasizes the frustration of the effort going to waste.","jlpt":"N4","example":"せっかくここまで登ってきたのに","meaning":"even though; despite (expresses regret, complaint, or surprise)"},{"tip":"Used here for a sequential action where the second action (shouting) follows naturally or immediately after the first (thinking).","pattern":"V-dict + と (to)","example":"そう思うと、犍陀多は大声で叫びました。","meaning":"when; if; indicates that an action results in a certain outcome or discovery","jlpt":"N4"},{"pattern":"～ではないか / ～ではありませんか (dewa nai ka)","tip":"In literature, this is often used to highlight a surprising discovery or to draw the reader's attention to a fact.","jlpt":"N3","example":"ついているではありませんか。","meaning":"isn't it? (rhetorical question used for emphasis or discovery)"},{"pattern":"V-plain past + 瞬間 (shunkan)","tip":"Literally translates to 'the moment that [verb] happened.' It is stronger and more specific than just saying 'when'.","jlpt":"N3","example":"その言葉が口から出た瞬間でした。","meaning":"the moment that...; as soon as..."},{"jlpt":"N2","example":"何かを言う間もなく","meaning":"without even time to...; before one can even...","pattern":"V-dict + 間もなく (ma mo naku)","tip":"A formal way to say that something happened so quickly there wasn't even time for the preceding action."}],[{"meaning":"Expresses a state or ongoing action (Present Progressive/State)","tip":"For verbs of motion or change (like 'dropping'), it often describes the resulting state.","example":"垂れているだけでした","pattern":"〜ている","jlpt":"N5"},{"pattern":"（意向形）＋とする","example":"自分だけが助かろうとした","jlpt":"N4","tip":"Use this when someone is making an effort to achieve something in that moment.","meaning":"Volitional form (+ とした) means trying to do or about to do something."},{"jlpt":"N4","example":"地獄に落ちたとき","pattern":"～とき","tip":"Nouns before 'toki' need 'no', and Na-adjectives need 'na'. Verbs can be dictionary or past tense.","meaning":"When...; at the time that..."},{"pattern":"～のように","example":"足元でいつものように","jlpt":"N3","tip":"Use this to describe actions or states that mimic or resemble a certain pattern or noun.","meaning":"Just like...; in the same way as..."},{"meaning":"Honorific form of 'to see' (miru).","tip":"This is many levels more polite than 'miru'. You use it for people of higher status, like the Buddha.","jlpt":"N3","pattern":"ご覧になる","example":"その一部始終をご覧になっていました"},{"meaning":"Indicates an action or state that continues from the present into the future, or moves away from the speaker.","jlpt":"N3","example":"広がっていくのでした","pattern":"～ていく / ～てくる","tip":"In this context, it shows the scent spreading outward away from the center of the lotus."},{"tip":"The combination suggests a regrettable outcome that the speaker is inferring from the situation.","jlpt":"N3","pattern":"～てしまう + ～でしょう","example":"その糸を切ってしまったのでしょう","meaning":"To do something completely (often with regret) + probably/must be."}]],"original":[[{"jlpt":"N5","example":"小さな蜘蛛が一匹、路ばたを這って行くのが見えました。","tip":"In older literature like this text, it is often written as '居る' instead of the modern hiragana 'いる'.","pattern":"～ている (～て居る)","meaning":"Indicates that an action is currently occurring or describes a continuous state."},{"meaning":"To try to do something, or be about to do something.","jlpt":"N4","pattern":"～（よ）うとする","tip":"Use the volitional form of the verb + 'とする'. It often implies an attempt that didn't fully happen.","example":"踏み殺そうと致しましたが..."},{"jlpt":"N3","pattern":"～に違いない","tip":"It follows nouns and verbs directly. It expresses the speaker's confidence based on some evidence.","example":"命のあるものに違いない。","meaning":"Used to express a strong certainty; 'must be' or 'without a doubt'."},{"jlpt":"N4","tip":"Be careful! This can sound rough or condescending if used toward superiors or equals. Use '～てあげる' in polite conversation.","pattern":"～てやる","example":"助けてやったからでございます。","meaning":"To do something for someone of lower status (or animals/plants)."},{"meaning":"An honorific (sonkeigo) construction used to show deep respect toward the subject's actions.","jlpt":"N3","example":"御歩きになっていらっしゃいました。","tip":"This is a standard way to turn a regular verb into a respectful one. In this text, the author uses '御' for 'お'.","pattern":"お＋Verb stem＋になる"},{"meaning":"Indicates what someone is thinking or intending to do.","jlpt":"N3","example":"この男を地獄から救い出してやろうと御考えになりました。","tip":"The volitional form followed by 'と' marks the content of the thought or decision.","pattern":"～（よ）うと思う / 考える"},{"meaning":"If possible; if it can be done.","jlpt":"N3","tip":"'Noun/Verb + なら' is used to provide a suggestion or talk about a condition previously mentioned.","pattern":"Ｖ（辞書形）＋なら","example":"できるなら、この男を地獄から救い出してやろう..."}],[{"meaning":"Listing actions that happen alternatingly or representative actions among many.","jlpt":"N5","tip":"The final 'suru' verb determines the tense of the entire sentence.","example":"浮いたり沈んだりしていた","pattern":"～たり ～たりする"},{"tip":"It often carries a slightly negative or critical nuance, like 'doing nothing but...'.","example":"もがいてばかり居りました","pattern":"～てばかりいる","meaning":"Doing nothing but X; indicates that an action is continuous or repetitive.","jlpt":"N4"},{"jlpt":"N2","meaning":"There is no doubt that...; certainly. (Formal equivalent of に違いない)","tip":"Common in literature or formal reports to express strong certainty.","pattern":"～に相違ない / ～に相違ございません","example":"地獄からぬけ出せるのに相違ございません"},{"tip":"Often used with 'ikura' (no matter how much) to emphasize a futile effort.","example":"いくら焦って見た所で","pattern":"～たところで","meaning":"Even if; no matter how much (something is done), it won't lead to the desired result.","jlpt":"N2"},{"jlpt":"N2","meaning":"It was worth doing; indicating a positive result from an effort.","pattern":"～た甲斐がある / ～た甲斐があって","example":"一生懸命にのぼった甲斐があって","tip":"Use this when a hard effort results in a rewarding outcome."},{"meaning":"Extremely; words cannot describe how... (often emphasizing a feeling).","jlpt":"N2","tip":"This structure is used to express that a quality or emotion is at an extreme level.","example":"その心細さと云ったらございません","pattern":"～といったら（あ）ない / ～といったらございません"},{"jlpt":"N3","meaning":"Even; so much as (emphasizes a surprising extreme).","pattern":"～さえ / ～さえ～ない","example":"泣声を出す力さえなくなっている","tip":"In negative sentences, it emphasizes that even the most basic thing is impossible."}],[{"jlpt":"N4","example":"落ちてしまいました","pattern":"～てしまう","tip":"In speech, this can shorten to -chau or -jau. Here it emphasizes the finality of falling into hell.","meaning":"To do something completely (often with regret/unintended)"},{"jlpt":"N4","example":"細く光りながら","tip":"The focus is usually on the second action; the thread is hanging while it is glowing.","pattern":"～ながら","meaning":"While doing (simultaneous actions)"},{"example":"莫迦のように大きな口を開いたまま","tip":"Used when a state that should normally change persists. He kept his mouth open in shock.","pattern":"～たまま","jlpt":"N3","meaning":"Leaving something in a certain state; unchanged state"},{"example":"落ちてしまうのに違いありません","pattern":"～に違いありません","tip":"A formal version of ~ni chigainai, expressing strong certainty based on logic.","jlpt":"N3","meaning":"There is no doubt that...; must be..."},{"pattern":"～さえ","tip":"It highlights that even the minimum possible requirement (just one person) is enough to break the thread.","example":"自分一人でさえ断れそうな","jlpt":"N3","meaning":"Even; a particle emphasizing an extreme case"},{"meaning":"If one does not do... (negative conditional)","example":"今の中にどうかしなければ","pattern":"～なければならない / なれば","tip":"Usually part of 'must', but 'nakereba' on its own implies 'if I don't [do something, something bad will happen].'","jlpt":"N3"},{"tip":"The humble form (-itashimashitara) of 'to shitara'. It sets up a hypothetical scenario.","pattern":"～と致しましたら (～としたら)","example":"断れたと致しましたら","jlpt":"N2","meaning":"Assuming that...; even if we suppose..."},{"example":"堪える事が出来ましょう","tip":"In literary styles, -mashou can express a rhetorical 'How could it be possible?' (deshou ka).","pattern":"～ましょう (Rhetorical)","jlpt":"N2","meaning":"Volitional form of 'deshou' used as a rhetorical wonder/probability"}],[{"meaning":"Honorific form of ~ている (to be doing)","tip":"This is used to describe the continuous action of a respected person, like Buddha in this text.","example":"見ていらっしゃいましたが","pattern":"～ていらっしゃる","jlpt":"N4"},{"meaning":"Expresses completion of an action or a regrettable result.","example":"沈んでしまいますと","pattern":"～てしまう","jlpt":"N4","tip":"In this context, it emphasizes the finality and misfortune of Kandata sinking back into Hell."},{"pattern":"V-stem + 始める","example":"御歩きになり始めました","jlpt":"N4","tip":"Attach this to the stem of a verb to indicate the start of an action or habit.","meaning":"To begin or start doing something."},{"meaning":"While doing; two actions occurring simultaneously by the same person.","jlpt":"N4","example":"悲しそうな御顔をなさりながら","pattern":"V-stem + ながら","tip":"The action after 'nagara' is usually the main focus of the sentence."},{"pattern":"Volitional Form + とし（てい）る","example":"地獄からぬけ出そうとする","jlpt":"N3","tip":"It often indicates an attempt to do something or a state where something is just about to happen.","meaning":"To try to, or be about to do something."},{"tip":"'Gozaimashou' is the very formal version of 'deshou', used in storytelling or polite speech.","jlpt":"N3","example":"落ちてしまったのが･･･浅間しく思召されたのでございましょう。","pattern":"～ので（ござい）ましょう","meaning":"Explaining a reason, or guessing based on evidence (formal)."},{"tip":"This is a standard way to show respect to the subject (the one performing the action).","jlpt":"N3","example":"御歩きになり始めました","pattern":"お / 御 + V-stem + になる","meaning":"Very polite/honorific expression of an action."}]]},"rashomon":{"simplified":[[{"tip":"Use 'no wa' for subjects and 'no o' for objects. It allows you to talk about actions as if they are things.","meaning":"Turns a verb or clause into a noun (nominalization).","example":"泥棒になるのは嫌だ","jlpt":"N5","pattern":"～のは / ～のが / ～のを"},{"tip":"Use the dictionary form for positive changes and the 'nai' form (e.g., konaku naru) for negative changes.","meaning":"Indicates a change that happens over time or reaching a certain state.","jlpt":"N4","example":"動物や泥棒が住むようになりました。","pattern":"V-dictionary form + ようになる"},{"tip":"Often translated as \"whenever\" or \"if.\" It's used for things that happen naturally, like seasonal changes or habitual actions.","pattern":"～と","example":"夕方になると、みんな怖がって門の近くに来なくなりました。","jlpt":"N4","meaning":"Natural consequence or an automatic result; 'whenever A happens, B follows.'"},{"tip":"In Japanese, the passive is often used to express a sense of being bothered or affected by someone else's action.","meaning":"Passive voice; indicates that something was done to the subject.","jlpt":"N4","example":"「もう来なくていい」と言われました。","pattern":"V-passive (～られる)"},{"tip":"Use this when you have a logical reason to believe something is true. Note that 'shika... nai' means 'only.'","pattern":"～はずだ","example":"死んだ人しかいないはずです。","jlpt":"N3","meaning":"Expectation or strong belief that something should be the case."},{"meaning":"Doing two actions at the same time.","jlpt":"N3","example":"おばあさんは震えながら言いました。","pattern":"V-stem + ながら","tip":"The second action (the verb after 'nagara') is the main focus of the sentence."},{"tip":"While 'te kuru' usually implies moving toward the speaker/present, 'te iku' implies moving away from the present toward the future.","pattern":"V-te + いく","jlpt":"N3","example":"どうやって生きていけばいいかわかりませんでした。","meaning":"Expresses a progression or change starting from now and continuing into the future."},{"tip":"Use this to show that a result occurs regardless of the condition. It's the 'even if' pattern.","pattern":"V-te + も","meaning":"Even if... (concessive conditional).","example":"俺がお前の服を盗んでも怒るなよ。","jlpt":"N2"}]],"intermediate":[[{"pattern":"～の（を/が）","jlpt":"N4","meaning":"Nominalizing a verb/sentence so it can function as an object.","example":"雨がやむのを待っていた。","tip":"Use 'no' instead of 'koto' when the main verb involves perception (to see/hear) or waiting."},{"jlpt":"N4","pattern":"～ようになる / ～なくなる","tip":"Connects to dictionary form for 'become' and negative form for 'stop happening'.","example":"夕方になると誰も近づかなくなった。","meaning":"Indicates a change in state or habit (to become...)."},{"pattern":"～そうだ (appearance)","jlpt":"N4","meaning":"Expressing that something looks or appears a certain way.","example":"雨宿りをする人がいそうだが。","tip":"For 'i-adjectives', drop the final 'i'. For 'ii' (good), it becomes 'yosasou'."},{"meaning":"Used for emphasis to mean 'even' or 'to the extent that'.","tip":"It implies an extreme or unexpected level that goes beyond the normal range.","example":"死体を捨てていく習慣までできた。","jlpt":"N3","pattern":"～まで"},{"meaning":"Asking for advice or expressing uncertainty about what to do.","tip":"Commonly used with question words like 'doushite' or 'doyatte' to show confusion.","example":"どうやって生きていけばいいのか分からず。","jlpt":"N4","pattern":"～ばいい（か）"},{"pattern":"～かもしれない","jlpt":"N4","example":"死人の髪を抜くのは悪いことかもしれない。","tip":"In casual speech, this is often shortened to just 'kamo'.","meaning":"Expressing a possibility or something that 'might' be true."},{"jlpt":"N3","pattern":"～（な）ければ","tip":"This is the negative conditional form. It is often used to explain a necessary action or consequence.","example":"そうしなければ飢え死にしていたからだ。","meaning":"If that were not the case (conditional negative)."},{"meaning":"A strong prohibition (Don't do...!).","example":"俺が身ぐるみ剥いでも恨むなよ。","tip":"This is very blunt and masculine. Be careful not to use it with superiors!","pattern":"Verb (Dictionary Form) + な","jlpt":"N4"}]],"original":[[{"meaning":"Used to turn a verb/sentence into a noun so it can be the object of a verb.","jlpt":"N5","example":"雨のふるのを眺めていた。","pattern":"Verb (Plain) + の","tip":"Unlike すること, の is often used for things you perceive with your senses, like seeing or hearing."},{"tip":"Use 見える for things that come into your line of sight naturally, and 見られる for having the opportunity to see something.","pattern":"～が見える","example":"鴉の糞が、点々と白くこびりついているのが見える。","jlpt":"N4","meaning":"Indicates that something is visible or can be seen (state), rather than the act of looking."},{"pattern":"～ている","tip":"In literature, this often sets the scene or describes the ongoing state of a character.","jlpt":"N4","meaning":"Expresses a continuous action or a current state.","example":"雨やみを待っていた。"},{"tip":"It is based on objective reasons or logical deduction. In this text, it's used with 'beki' (should) for extra emphasis on duty.","pattern":"～はずだ / ～はずである","example":"主人の家へ帰る可き筈である。","jlpt":"N3","meaning":"Expresses a strong expectation or something that is naturally supposed to be the case."},{"tip":"Determines a sense of urgency or a lack of resources (physical or temporal).","pattern":"～余裕／暇（いとま）はない","example":"手段を選んでいる遑はない。","meaning":"Indicates that there is no time, room, or margin to do something.","jlpt":"N3"},{"pattern":"～以上（は）","tip":"The second part of the sentence often contains a judgment, a duty, or a logical necessity.","meaning":"Now that; since; as long as. Expresses a strong resolve or an inevitable consequence based on a fact.","jlpt":"N2","example":"朱雀大路にある以上は、..."},{"example":"衰微の小さな余波にほかならない。","jlpt":"N2","meaning":"Nothing but; none other than. Used to emphasize a definitive reason or identity.","tip":"This is a formal expression used to assert that there is no other possible explanation.","pattern":"～にほかならない"},{"example":"考えをたどった揚句に、...","meaning":"After a long process of... (usually leading to a negative or complicated result).","jlpt":"N2","tip":"It implies that someone went through a lot of trouble or spent a long time doing something, often to reach a difficult conclusion.","pattern":"～あげく（に）"}]]},"hashire-merosu":{"simplified":[[{"jlpt":"N5","tip":"In casual speech, the 'i' is often dropped (e.g., 非んでる).","pattern":"～ている","meaning":"indicates a continuous action or current state","example":"羊と遊んで生活しています。"},{"meaning":"must; have to; it is necessary to...","example":"あの悪い王様を倒さなければならない","jlpt":"N4","pattern":"～なければならない","tip":"This is quite formal. In daily conversation, people often use 'nakucha' or 'nakya'."},{"tip":"Use this when the second action happens almost automatically after the first.","pattern":"～と (conditional)","jlpt":"N4","example":"町を歩いていると、メロスは「変だな」と思いました。","meaning":"when; if; whenever (leads to an inevitable or natural result)"},{"meaning":"in order to; for the purpose of","example":"食べ物を買うために、町に来たのです。","jlpt":"N4","tip":"When used with a verb, the verb must be in the dictionary form. Use 'Noun + no' for nouns.","pattern":"～ために"},{"pattern":"～つもりだ","tip":"This expresses a strong intention or a plan that has already been decided in your mind.","jlpt":"N4","example":"メロスは彼に会いに行くつもりでした。","meaning":"plan to; intend to"},{"pattern":"～という","tip":"This is great for introducing yourself or a place someone might not know yet.","jlpt":"N4","example":"セリヌンティウスという大切な友だち","meaning":"called; named (used to introduce a name or title)"},{"tip":"Unlike English 'more', 'motto' doesn't require a 'than' phrase; it just emphasizes an increase in degree.","pattern":"もっと","jlpt":"N3","example":"前はもっとにぎやかでしたよ。","meaning":"more (comparative)"}],[{"meaning":"Wanting to do something (verb stem + tai)","example":"妹の結婚式をしたいのです。","pattern":"～たい","jlpt":"N5","tip":"It is used for the speaker's own desires. Use it with the verb stem."},{"tip":"Often used when a state continues unexpectedly or regardless of the next action.","pattern":"～まま","jlpt":"N4","example":"怒ったまま王様のお城に入りました。","meaning":"Leaving something in a certain state; as it is"},{"tip":"When used with a verb, the verb must be in the dictionary form (plain present).","jlpt":"N4","pattern":"～ため（に）","example":"町を、あなたから助けるためだ","meaning":"For the purpose of; in order to"},{"tip":"Use the dictionary form for positive intentions and the 'nai' form for negative intentions.","jlpt":"N4","pattern":"～つもり","example":"何をするつもりだったか？","meaning":"Intending to do something; planning to do"},{"meaning":"Passive voice (to be done to)","example":"すぐに兵士に捕まりました。","pattern":"～られる / ～れる","jlpt":"N4","tip":"In this text, 'tsukama-ru' (to be caught) and 'tsurete-ika-reru' (to be taken) are passive forms."},{"example":"もし私が信じられないなら","meaning":"If; provided that (conditional)","tip":"Used to provide a suggestion or reaction based on a context just mentioned or a hypothetical situation.","jlpt":"N4","pattern":"～なら"},{"meaning":"Volitional form (Let's / I will) + giving a favor (to a social inferior/animal)","example":"あの友だちを殺してやろう。","pattern":"～てやろう","jlpt":"N4","tip":"'Yaru' is the humble/rough version of 'ageru'. Here it shows the King's cruel intent."}],[{"example":"雨がたくさん降りましたが","jlpt":"N5","pattern":"～が","meaning":"But / However (connecting two sentences)","tip":"It connects a positive and negative situation, or simply provides a contrast."},{"meaning":"Let's (Volitional form)","pattern":"～（よ）う","tip":"Use this to suggest an action to someone or to express your own intention.","example":"結婚式をしよう","jlpt":"N4"},{"example":"お城に呼ばれました / 縄で縛られました","jlpt":"N4","pattern":"～られる / ～れる","meaning":"Passive voice (to be done something)","tip":"Use this when the subject is the receiver of the action. It's common in storytelling."},{"jlpt":"N4","example":"ずっとここにいたい","tip":"Drop the 'masu' from a verb and add 'tai' to express desire. Use it only for your own desires.","pattern":"V-stem + たい","meaning":"Want to do something"},{"example":"顔を赤くしました","jlpt":"N4","meaning":"To make something (adjective) / To change state","pattern":"Adj + する / なる","tip":"For い-adjectives, change い to く. For な-adjectives, add に. 'Suru' implies an intentional action."},{"pattern":"～なければなりません","meaning":"Must / Have to do something","tip":"This literally means 'If you don't do it, it won't do.' It is the formal way to express obligation.","example":"行かなければなりません","jlpt":"N4"}],[{"jlpt":"N4","example":"走り出しました","meaning":"to begin or start an action suddenly","pattern":"～出す (V-stem + 出す)","tip":"Use this for actions that start suddenly or outwardly, like rain starting or someone bursting into laughter."},{"example":"泣きながら神様にお願いしました","jlpt":"N4","pattern":"～ながら (V-stem + ながら)","meaning":"doing two actions at the same time","tip":"The main action always comes second. In this case, 'praying' is the primary action while crying."},{"jlpt":"N3","example":"雨のせいで川の水がいっぱいになっていました","meaning":"because of; due to (usually for a negative result)","pattern":"～のせいで (Noun + のせいで / Verb + せいで)","tip":"Think of this as \"blaming\" something. Use 'okage de' if the result is positive."},{"example":"私には命しかありません","jlpt":"N4","pattern":"～しか～ない (Noun + しか + Negative Verb)","meaning":"only; nothing but (used with negative verbs)","tip":"It emphasizes that there is nothing else. It always pairs with a negative verb, even though the English translation sounds positive."},{"meaning":"to become; to reach a new state or change","pattern":"～くなる / ～になる (Adj/Noun + なる)","tip":"Pair with 'nai' form (moving -> not moving) to show a change in ability or condition.","jlpt":"N4","example":"足が動かなくなりました"},{"tip":"Use this for 'natural consequences' or to describe the next thing you noticed after an action.","meaning":"when (X happens, Y follows immediately or naturally)","pattern":"～と (Verb Dictionary Form + と)","jlpt":"N4","example":"川を渡ると、今度は山賊が来ました"},{"meaning":"must; have to (obligation)","pattern":"～なければならない (V-nai form + ければならない)","tip":"In casual speech, this is often shortened to 'nakya' or 'nakucha'.","jlpt":"N4","example":"走らなければならない"}],[{"example":"風のように","meaning":"like; similar to (describing an action/state)","pattern":"Noun + のように","tip":"Use 'のように' for actions (verbs) and 'のような' for things (nouns). Think of it as 'in the manner of'.","jlpt":"N4"},{"jlpt":"N5","tip":"This is the standard way to speak politely about completed actions in the past.","pattern":"Verb (Masu-stem) + ました","meaning":"Polite past tense suffix for verbs.","example":"走りました"},{"jlpt":"N4","tip":"Use the dictionary form for 'about to happen,' the -te iru form for 'in the middle of,' and the -ta form for 'just finished'.","pattern":"Verb (Dictionary Form) + ところだ/です","meaning":"About to do; on the verge of (happening).","example":"沈むところでした"},{"pattern":"Verb (Nai-stem) + れる / られる","tip":"In passive sentences, the person who was affected by the action is the subject. For Ichidan verbs, add -rareru; for Godan, change the last vowel to 'a' and add -reru.","jlpt":"N4","example":"殺されるところでした","meaning":"Passive voice (to be done/to be acted upon)."},{"meaning":"The -te form used to connect sentences or indicate a sequence of events.","example":"十字架にかけられて","jlpt":"N5","pattern":"Verb (Te-form)","tip":"In this context, it shows that one action (being put on the cross) happened before the next (being killed)."}],[{"example":"人を信じることは嘘ではない。","meaning":"Nominalizing a verb to make it a subject or object (The act of...)","tip":"Use 'koto' to transform an action into a noun so you can say something 'is' good, hard, or important.","pattern":"V-辞書形 + こと","jlpt":"N5"},{"jlpt":"N5","pattern":"～ている / ～ていない","meaning":"State of being / Continuous action (negative past)","tip":"For clothing, 'te-iru' describes the state of wearing it, not the act of putting it on.","example":"服を着ていませんでした。"},{"tip":"Use this when someone intentionally changes one thing into another.","meaning":"Make/Change something into a certain state or category","pattern":"Noun + にする","jlpt":"N4","example":"私をあなたたちの友だちにしてくれないか。"},{"example":"あなたを抱きしめることができません。","jlpt":"N4","pattern":"V-辞書形 + ことができる","meaning":"Potential (can/cannot do)","tip":"This is a more formal way to express potential compared to the potential verb form (e.g., daki-shimeru vs daki-shimerareru)."},{"example":"あなたにたたかれないと、...","jlpt":"N4","pattern":"V-ない形 + と","meaning":"Conditional 'if' / 'unless' (If A doesn't happen, B (result) follows naturally)","tip":"The 'Verb-nai + to' pattern often expresses that the second action is impossible without the first."},{"example":"あきらめようとしました。","pattern":"V-意向形 (Volitional) + と（する）","jlpt":"N3","tip":"Use this to describe what someone was trying to do or was just about to start doing.","meaning":"Attempting to do something / About to do something"},{"meaning":"To become (change in state)","tip":"This shows a transition. 'Hazukashiku naru' implies Melos wasn't embarrassed at first, but then he became so.","jlpt":"N3","pattern":"い-Adj（～く） + なる / な-Adj + になる","example":"メロスはとても恥ずかしくなって、..."}]],"intermediate":[[{"pattern":"～うちに","meaning":"While; during the time when (an action is ongoing)","tip":"Think of it as 'while the state hasn't changed.' In this text, it refers to the duration of his walk.","example":"歩いているうちに","jlpt":"N3"},{"jlpt":"N4","example":"友人を訪ねるつもりだ","tip":"Used for personal intentions. For official schedules, use 'yotei' (予定) instead.","pattern":"～つもりだ","meaning":"Intend to; plan to"},{"jlpt":"N4","example":"迎えることになっていた","tip":"Use this when a decision was made by an outside force or as a social arrangement, rather than a personal whim.","meaning":"It has been decided that...; it is a rule or custom that...","pattern":"～ことになっている"},{"tip":"This expresses strong confidence. Here, Melos is confused because reality doesn't match his logical expectation.","meaning":"Should be; I expect that (based on evidence or logic)","pattern":"～はずだ","jlpt":"N4","example":"にぎやかだったはずだが"},{"jlpt":"N4","example":"倒さなければならない","tip":"Formed by taking the negative (nai) form, dropping 'i', and adding 'kereba naranai'. It's common in formal writing and strong speech.","pattern":"～なければならない","meaning":"Have to; must (literally: if you don't..., it won't do)"},{"example":"生かしておくわけにはいかない","jlpt":"N2","meaning":"Cannot; must not (due to social/moral reasons)","pattern":"～わけにはいかない","tip":"This isn't about physical ability, but about being unable to do something because it would be wrong or irresponsible."}],[{"jlpt":"N4","tip":"Think of it as 'as is' or 'leaving it in the state of...' It often follows the past tense (~た).","pattern":"～まま","meaning":"Indicates that a state remains unchanged while another action occurs.","example":"荷物を背負ったまま"},{"jlpt":"N4","pattern":"～はずがない","tip":"This is much stronger than a simple 'no.' It expresses the speaker's total disbelief based on logic.","meaning":"Expresses a strong conviction that something is impossible or will not happen.","example":"帰ってくるはずがない"},{"example":"結婚式を挙げさせ","meaning":"The causative form, used to indicate making or letting someone do something.","tip":"In this context (the sister's wedding), it implies 'making arrangements' or 'facilitating' rather than forcing.","pattern":"～させる (使役形)","jlpt":"N4"},{"meaning":"Expresses a condition; used to give advice, make a suggestion, or state a premise.","example":"情けをかけたいと思うなら","jlpt":"N3","tip":"Unlike 'tara' or 'to', 'nara' focuses on the context provided by the previous speaker or the current situation.","pattern":"～なら"},{"example":"身代わりを呼ぶがいい","meaning":"Used to give a strong suggestion or command, often implying it's the only or best logical choice.","pattern":"～がいい / ～がいいだろう","tip":"Coming from a King, this sounds like a command or a permission given with an air of authority.","jlpt":"N2"},{"pattern":"～ていればいい / ～ていればよい","tip":"Often implies sarcasm or indifference toward the subject's behavior.","jlpt":"N2","example":"うぬぼれていればいい","meaning":"Expresses that the speaker doesn't care about the other person's action or state; 'go ahead and...'."},{"jlpt":"N2","tip":"This expresses a strong intent to make someone experience something, often with a vengeful or superior undertone.","pattern":"～（さ）せてやる","meaning":"A combination of the causative (make someone realize) and the 'giving action' to an inferior (yaru).","example":"思い知らせてやりたい"}],[{"tip":"Drop the -masu from a verb and add 'nasai'. It is firm but polite.","example":"知らせてきなさい","meaning":"A command pattern softer than the imperative form, often used by parents or teachers.","jlpt":"N5","pattern":"～なさい"},{"meaning":"Indicates the sudden start of an action or phenomenon.","example":"雨が降り出し","tip":"Use the verb stem + dasu. It is commonly used for natural phenomena like rain or wind.","pattern":"～出す / ～出し","jlpt":"N4"},{"pattern":"～ずに","jlpt":"N3","meaning":"A formal way to say 'without doing', equivalent to 'shinai de'.","example":"一睡もせずに","tip":"Replace the 'nai' of a negative verb with 'zu ni'. 'Suru' becomes 'sezu ni'."},{"jlpt":"N3","pattern":"～かのような / ～かのように","meaning":"Used to describe something that appears to be or behaves as if it were something else.","tip":"It expresses a metaphor or a strong resemblance to something that isn't necessarily true.","example":"一瞬もしていないかのような"},{"pattern":"Volitional + とした / と属性","jlpt":"N3","meaning":"Indicates that someone is making an effort to do something or is just about to start.","example":"無理に笑おうとした","tip":"Use the volitional form (e.g., ikou, tabeyou) + to suru. It often implies a struggle or an attempt."},{"pattern":"～なければならない","jlpt":"N4","meaning":"Indicates obligation or necessity (must do).","example":"町へ行かなければならない","tip":"This is the standard way to express 'must'. In speech, it often shortens to 'nakya'."},{"example":"早いほうがいいだろう","tip":"Pair it with the past tense (ta-form) for a stronger recommendation or the dictionary form for a general preference.","meaning":"Used to give advice or suggest that one option is preferable to another.","pattern":"～ほうがいい","jlpt":"N4"},{"meaning":"Expresses a conjecture, guess, or probability.","example":"雨も弱まっているだろう","tip":"It is the plain form of 'deshou'. It can also be used to seek agreement with a rising intonation.","pattern":"～だろう / ～でしょう","jlpt":"N4"}],[{"meaning":"Must do; to have an obligation to do something.","tip":"In casual speech, this is often shortened to '～なきゃ'.","jlpt":"N5","example":"走らなければならない。","pattern":"～なければならない"},{"pattern":"～ながら","example":"自分を励ましながら走った。","jlpt":"N4","tip":"The focus is usually on the second (main) verb.","meaning":"While doing; used to describe two actions happening simultaneously by the same person."},{"tip":"Using 'も' instead of 'は' emphasizes that this is just one of many things that aren't necessary.","meaning":"No need to...; it is not necessary to do something.","example":"そんなに急ぐ必要もない。","jlpt":"N4","pattern":"～（辞書形）必要はない/もない"},{"jlpt":"N3","example":"泳ぎ切るしかない。","pattern":"～切る / ～しかない","tip":"'V-切る' means to finish completely; 'しか～ない' expresses that there are no other options available.","meaning":"To do something to the very end / Have no choice but to..."},{"pattern":"～ように","jlpt":"N3","example":"濁流はメロスの叫びを笑うように...","tip":"When used with a verb before it, it describes how an action is performed or how something appears metaphorically.","meaning":"As if; similar to; used to describe an appearance or a manner."},{"tip":"Make sure to use the past tense (た-form) before '時' if the action was completed before the main clause.","meaning":"When; as soon as (indicates a specific moment in time).","pattern":"～た時","example":"山道を登りきってほっとした時...","jlpt":"N3"},{"pattern":"～わけではない","jlpt":"N3","example":"私は決して君をだましたわけではない。","tip":"This is a soft way to clarify a misunderstanding or provide an excuse.","meaning":"It doesn't mean that...; It’s not the case that... (used to deny an inference)."}],[{"pattern":"～て (Conjunctive)","meaning":"The 'te-form' used to connect sequences of actions or states.","example":"村を過ぎて","tip":"Think of it as 'and' or 'then' when linking verbs in a sequence.","jlpt":"N5"},{"pattern":"V-stem + 出す","meaning":"Indicates that an action has started suddenly or began.","example":"走り出した","jlpt":"N4","tip":"Focuses on the outward movement or the sudden initiation of an action."},{"jlpt":"N3","tip":"Used for proportional changes (as one thing increases or changes, so does the other).","pattern":"V-dictionary form + につれて","meaning":"As A happens, B happens; indicates a simultaneous change in two things.","example":"走るにつれて"},{"example":"精神そのものになったような気がした","meaning":"To have a feeling that... or it feels like...","pattern":"～気がする","jlpt":"N3","tip":"Used for subjective feelings or intuitions rather than hard facts."},{"pattern":"V-dictionary form + だけ","meaning":"Nothing but; only; just. Emphasizes that no other action was taken.","example":"走るだけだった","tip":"In this context, it shows Melos's singular focus and lack of other options.","jlpt":"N3"},{"pattern":"Volitional Form + としている","meaning":"To be about to do something; on the verge of.","example":"太陽はまさに沈もうとしていた","tip":"Used for actions that are just about to happen naturally or by someone's intent.","jlpt":"N2"},{"jlpt":"N2","tip":"Use this when you want to emphasize the specific 'point in time' an action is occurring.","meaning":"At the very moment of doing something. Adds specific timing to the 'about to' action.","example":"突き刺そうとしているところだった","pattern":"V-dict / V-ている + ところだ"}],[{"pattern":"～ろ / ～れ (命令形)","example":"私を殺せ！","tip":"Common in fiction, military contexts, or between close male friends, but very rude in polite conversation.","meaning":"Imperative form (Command) used to give direct orders.","jlpt":"N4"},{"meaning":"Indicates two actions happening simultaneously by the same person.","tip":"The main action comes after 'nagara'. Here, shouting is secondary to pushing through the crowd.","jlpt":"N4","pattern":"V-stem + ながら","example":"叫びながら"},{"meaning":"The 'if' condition (ba-form) combined with receiving a favor (kureru).","tip":"Use this when saying 'If you don't do (something) for me'. It emphasizes the speaker's need for the action.","jlpt":"N4","pattern":"～てくれなければ","example":"殴ってくれなければ"},{"tip":"It's used here to describe the quality or magnitude of a sound by comparing it to 'resounding'.","meaning":"Used to describe something by comparing it to something else (metaphor/simile).","jlpt":"N3","pattern":"～ような + Noun","example":"響き渡るような音"},{"pattern":"～てしまう / ～てしまった","example":"君を疑ってしまった。","tip":"In this context, it emphasizes Selinuntius's deep guilt and regret for doubting his friend.","meaning":"Expresses completion of an action, often with a sense of regret or accidental occurrence.","jlpt":"N4"},{"pattern":"～てくれないか","example":"仲間に入れてくれないか。","meaning":"A casual request or invitation formulated as a question.","tip":"It's softer than a command and is often used by men to ask for a favor or permission.","jlpt":"N4"},{"pattern":"～てたまらない","example":"恥ずかしくてたまらない","meaning":"Indicates that a feeling or sensation is so strong it is unbearable/irresistible.","tip":"Usually used with emotions (sadness, joy) or physical sensations (thirst, itchiness).","jlpt":"N3"}]],"original":[[{"jlpt":"N4","example":"羊と遊んで暮して来た。","tip":"Think of it as an action \"coming\" toward the current moment in time.","pattern":"～てくる (～てきた)","meaning":"Indicates an action or state that has continued from the past up to the present."},{"tip":"Use this for scheduled events or social rules rather than personal willpower.","meaning":"Indicates an appointment, a rule, or a decision made by someone else or a situation.","pattern":"～ことになっている","jlpt":"N4","example":"花婿として迎える事になっていた。"},{"example":"まちは賑やかであった筈だが","jlpt":"N4","pattern":"～はずだ","meaning":"Expresses a strong expectation or belief that something should be the case.","tip":"It reflects the speaker's expectation based on logic or past experience."},{"tip":"In this context, it implies a change happened naturally as time passed during the walk.","pattern":"～うちに (～ているうちに)","meaning":"While a certain condition or action is continuing, a change occurs.","jlpt":"N3","example":"歩いているうちに"},{"tip":"'Te-miru' adds the nuance of 'giving it a try' to the intention.","pattern":"～てみる + つもりだ","meaning":"Expresses an intention or plan to try doing something to see the result.","jlpt":"N3","example":"訪ねてみるつもりなのだ。"},{"meaning":"Literary/Old-fashioned version of 'must' (nakereba naranai). 'Nu' is a classical negation.","pattern":"～なければならぬ (ならない)","tip":"'Naranu' is more formal and resolute, fitting for the epic tone of this story.","example":"除かなければならぬ","jlpt":"N2"},{"pattern":"～をはばかる (憚る)","meaning":"To hesitate or hold back due to social pressure or others' presence.","tip":"Commonly used in the phrase 'atashi wo habakaru' (mindful of surroundings).","example":"あたりをはばかる低声で","jlpt":"N1"}],[{"pattern":"～たまま / ～たままで","example":"買い物を、背負ったままで","meaning":"State of remaining unchanged; doing something while keeping a certain condition","tip":"Commonly used when an action results in an unexpected or inappropriate state, like 'wearing shoes inside'.","jlpt":"N4"},{"tip":"It expresses a strong intention in the speaker's mind, firmer than just a wish.","jlpt":"N4","meaning":"Intention or plan to do something","pattern":"～つもりだ / ～つもりであった","example":"この短刀で何をするつもりであったか。"},{"tip":"In this context, it emphasizes the subject. 'Even someone like me/Even I...'","jlpt":"N3","meaning":"Even/Also (emphasized)","pattern":"～だって / ～だって～のだが","example":"わしだって、平和を望んでいるのだが。"},{"example":"自分の地位を守る為か。","pattern":"～ため（に）","tip":"When attached to a noun or a verb dictionary form, it indicates a goal or purpose.","jlpt":"N3","meaning":"For the purpose of; for the sake of"},{"example":"信じては、ならぬ。","pattern":"～てはならぬ / ～てはならない","jlpt":"N3","tip":"'ならぬ' is an older/literary version of 'ならない'. It is used for strong prohibitions or social rules.","meaning":"Must not; should not (prohibition)"},{"pattern":"～にきまっている","example":"どうせ帰って来ないにきまっている。","tip":"Expresses a strong subjective conviction by the speaker. 'どうせ' (anyway/after all) often accompanies it to show a cynical or resigned attitude.","jlpt":"N3","meaning":"It is certain that...; bound to...; definitely..."},{"example":"人の腹綿の奥底が見え透いてならぬ。","pattern":"～てならぬ / ～てならない","meaning":"Cannot help but...; cannot resist... (unbearable emotion or physical state)","tip":"Use this for feelings or physical sensations that arise naturally and are hard to control. 'ならぬ' is the literary form.","jlpt":"N2"},{"tip":"Combining the causative (させる) with 'やりたい' expresses the desire to allow or make someone do something for their benefit.","jlpt":"N4","meaning":"Causing someone to do something (Causative) + giving a favor (To do for someone)","example":"亭主を持たせてやりたいのです。","pattern":"～（さ）せてやりたい / ～（さ）せる"}],[{"meaning":"Indicates an action in progress or a state that continued in the past.","example":"村人たちは野に出て仕事をはじめていた。","jlpt":"N5","pattern":"～ていた","tip":"In storytelling, this sets the background scene for the main events."},{"jlpt":"N4","pattern":"～なければならぬ","tip":"The ending 'nu' instead of 'nai' gives the character's speech a determined, slightly old-fashioned tone.","meaning":"Indicates obligation (must do). 'Naranu' is a formal/literary version of 'naranai'.","example":"またすぐ市に行かなければならぬ。"},{"meaning":"To try to do or attempt to perform an action.","example":"無理に笑おうと努めた。","pattern":"Volitional + と（する/努める）","jlpt":"N3","tip":"Use this when someone is making a conscious effort to do something difficult."},{"example":"結婚式を明日にしてくれ、と頼んだ。","meaning":"A quoted request; 'please do X'. Often used when reporting what someone asked for.","tip":"It is the informal/imperative version of '～てください', commonly used in narratives.","jlpt":"N3","pattern":"～てくれと（頼む/言う）"},{"pattern":"～まま","jlpt":"N3","tip":"In this context, it expresses the desire to stay in the current state/location forever.","meaning":"As it is; leaving a condition unchanged.","example":"このままここにいたい、と思った。"},{"pattern":"～ていたかった","jlpt":"N2","tip":"This combines the 'te-iru' (state) with 'tai' (want) in the past tense to show a lingering feeling.","meaning":"Wants to be in the state of doing something; indicates a persistent desire for a continuous action.","example":"少しでも永くこの家に愚図愚図とどまっていたかった。"},{"meaning":"Expresses the speaker's conjecture or strong probability regarding a current or future state (literary).","example":"雨も小降りになっていよう。","jlpt":"N1","pattern":"～ていよう","tip":"In modern Japanese conversation, we usually use '～ているだろう', but '～ていよう' is common in classic literature."}],[{"jlpt":"N5","example":"寝過したか、いや、まだまだ大丈夫。","pattern":"～か","meaning":"Indicates a question, doubt, or self-confirmation, often used in internal monologues.","tip":"In literature, 'ka' at the end of a sentence often represents a character's internal thought process or sudden realization."},{"example":"約束の刻限までには十分間に合う。","jlpt":"N4","meaning":"Indicates a time limit or deadline by which an action must be completed.","pattern":"～までに","tip":"Don't confuse this with 'made' (until). 'Made ni' is for a deadline (one-time action), while 'made' is for a continuous state."},{"example":"身代りの友を救う為に走るのだ。","jlpt":"N4","tip":"When preceded by a noun, keep the 'no' particle. It sounds more formal and determined than 'youni'.","meaning":"Used to express a purpose, objective, or reason for doing something.","pattern":"～ために / ～がために"},{"meaning":"Indicates obligation or necessity. 'Naru' is a classical/literary version of 'nai'.","pattern":"～なければならぬ (ならない)","tip":"In modern speech, you use 'naranai', but 'naru' is frequently seen in literature to give a sense of gravity or historical tone.","example":"走らなければならぬ。","jlpt":"N4"},{"example":"陽は既に西に傾きかけている。","jlpt":"N3","tip":"Usually used with verbs that describe a process, like 'dying', 'setting (sun)', or 'eating'.","meaning":"Indicates that an action or state has started but is not yet finished (halfway through).","pattern":"～かける / ～かけている"},{"tip":"This often implies that if you don't act now, the opportunity will pass or the situation will change for the worse.","pattern":"～ないうちに","meaning":"Means 'while' or 'before' something happens. Usually indicates a limited window of time.","jlpt":"N3","example":"あれが沈んでしまわぬうちに、王城に行き着くことが出来なかったら･･･"},{"example":"泳ぎ切るより他に無い。","jlpt":"N3","tip":"This pattern emphasizes a sense of determination or being cornered by circumstances.","meaning":"Expresses that there is no other choice or alternative but to do something.","pattern":"～よりほかにない / ～ほか（は）ない"},{"meaning":"While doing something; at the same time. Similar to 'nagara' but more formal/literary.","pattern":"～つつ / ～つつも","tip":"'Tsutsu mo' implies a contrast, similar to 'even though I was being...'. It is very common in written narratives.","example":"押し流されつつも、見事、対岸の樹木の幹に、すがりつく事が出来た。","jlpt":"N2"}],[{"pattern":"～れる / ～られる (Passive)","example":"私は信頼されている。","meaning":"The passive voice, used when the subject is the receiver of an action.","jlpt":"N5","tip":"In literature, this often emphasizes the mental or emotional state of the subject being acted upon by others."},{"example":"忘れてしまえ。","jlpt":"N4","meaning":"Indicates the completion of an action, often with a sense of regret or a command to finish it completely.","tip":"In the imperative form (~shimae), it expresses a strong determination or a forceful command to move past something.","pattern":"～てしまう / ～てしまえ (Imperative)"},{"example":"走れるようになったではないか。","meaning":"Indicates a change in ability or habit; becoming able to do something.","jlpt":"N4","tip":"Use this when describing a transition from 'cannot' to 'can'. In this text, it marks Melos's recovery of strength.","pattern":"～ようになる"},{"tip":"Combined with 'kudasai', it is a humble way to ask for permission ('Please let me...').","jlpt":"N4","meaning":"The causative form, meaning to make or let someone do something.","example":"正直な男のままにして死なせて下さい。","pattern":"～せる / ～させる (Causative)"},{"tip":"This is a more formal or dramatic version of 'shika nai', perfect for high-stakes situations.","meaning":"Expresses that there is no other way or choice but to do a specific action.","jlpt":"N3","example":"走るより他は無い。","pattern":"～より他はない (yori hoka wa nai)"},{"pattern":"～ところだ (tokoro da)","example":"あの方が死刑になるところです。","meaning":"Indicates that an action is about to happen or is in the middle of happening.","jlpt":"N3","tip":"The tense of the verb before 'tokoro' changes the nuance: dictionary form means 'just about to start'."},{"tip":"This is a nuanced way of saying 'it might happen' without sounding too certain. Use it for cautious optimism.","meaning":"A double negative used to suggest that something is not impossible, or there is a slight possibility.","jlpt":"N2","example":"ひょっとしたら、間に合わぬものでもない。","pattern":"～ないものでもない"},{"pattern":"(Volitional Verb) + とした時","example":"まさに最後の一片の残光も、消えようとした時...","jlpt":"N2","meaning":"Describes a moment when something was just about to happen (often interrupted by something else).","tip":"This creates a cinematic effect in storytelling, freezing the moment right before a major change occurs."}],[{"jlpt":"N5","pattern":"～てくる (て形 + 来る)","tip":"In this context, it shows physical movement toward the speaker's location, but it can also mean a process starting in the past and continuing to the present.","meaning":"Indicates the completion of an action or a change that results in the current state (to come to be).","example":"メロスが帰って来た。"},{"example":"叫びながら","meaning":"Indicates two actions happening simultaneously by the same person.","tip":"The main action always comes second. Here, 'crying out' is the background action while 'climbing the platform' is the main movement.","pattern":"～ながら (Stem + ながら)","jlpt":"N4"},{"example":"君が若し私を殴ってくれなかったら","meaning":"A conditional 'if' used to express a hypothetical situation or a specific result.","tip":"It is often paired with 'もし' (if) to emphasize the hypothetical nature of the sentence.","pattern":"～たら (Plain Past + ら)","jlpt":"N4"},{"example":"抱擁する資格さえ無いのだ。","meaning":"Emphasizes an extreme example to imply that other things are also true (even...; not even...).","tip":"It replaces particles like 'が' or 'を' and carries a nuance of 'something as basic as this'.","pattern":"～さえ (Noun + さえ)","jlpt":"N3"},{"example":"皆に見られるのが","meaning":"Used to indicate the passive voice, where the subject is the recipient of the action.","tip":"In Japanese, the passive is often used to express 'feeling troubled' by someone else's action (Suffering Passive).","pattern":"～られる (Passive Voice)","jlpt":"N4"},{"tip":"'まい' is a negative volitional suffix. This pattern asks 'Won't you do [action] for me?' and sounds very masculine and authoritative yet humble here.","jlpt":"N2","pattern":"～てくれまいか (て形 + くれまいか)","example":"仲間に入れてくれまいか。","meaning":"A formal or slightly archaic way to make a polite request or invitation (won't you?)."},{"meaning":"A strong, formal, or literary prohibition (must not).","example":"殺してはならぬ。","jlpt":"N2","pattern":"～てはならぬ / ～てはならない","tip":"'ならぬ' is the classical/literary form of 'ならない'. It is used for rules or solemn commands."}]]},"lemon":{"simplified":[[{"meaning":"Whenever A happens, B inevitably happens or follows. (Natural/conditional consequence)","example":"お酒を毎日飲んでいると","jlpt":"N4","tip":"Think of this as 'whenever' or 'if/when' for habitual actions or physical results.","pattern":"～と (Condition)"},{"meaning":"Describes a continuous state or an action currently in progress.","example":"ゴミが落ちている場所です。","jlpt":"N4","pattern":"～ている (State)","tip":"With verbs like 落ちる (to fall), this describes the 'state' after the fall (i.e., 'lying on the ground')."},{"example":"すぐに立ち上がって帰りたくなります。","meaning":"To want to do an action/verb.","jlpt":"N4","tip":"To use this with a verb, change the verb to the 'masu-form' stem and add 'tai'. It turns the verb into an i-adjective.","pattern":"～たい (Desire)"},{"pattern":"～そう (Appearance)","tip":"Attach this to the 'masu-form' stem. Be careful: for the negative 'doesn't look like', it changes significantly (e.g., なさそう).","jlpt":"N3","example":"壊れそうな町です。","meaning":"Something looks or seems likely to happen."},{"jlpt":"N3","meaning":"Expresses ability or possibility (cannot / can).","example":"部屋の中にいることができないのです。","tip":"This is a more formal or explicit way to talk about ability compared to the potential form (～れる/られる).","pattern":"～ことができる"},{"pattern":"～くらい / ～ぐらい","tip":"Use this when you want to use a specific situation as a yardstick to describe the intensity of an emotion or action.","jlpt":"N3","meaning":"To the extent that... / So much so that...","example":"どこを歩いているかわからないくらい、たくさん歩きました。"},{"jlpt":"N3","example":"病気のせいだけではありません。","meaning":"Indicates a reason for a negative outcome (because of/fault of).","pattern":"～せい (Reason/Fault)","tip":"Think of this as the 'bad' version of 'okage de' (thanks to). Use it only when the result is undesirable."}],[{"jlpt":"N5","tip":"Always use the dictionary (plain) form of the verb before ことが.","example":"何も買うことができませんでした。","meaning":"Used to express potential or ability (can/cannot do something).","pattern":"Dictionary Form + ことができる"},{"pattern":"何(も) + Negative Verb","example":"何も買うことができませんでした。","meaning":"Used followed by a negative verb to mean 'nothing', 'not anything', or 'not at all'.","tip":"In this context, the 'mo' acts like 'at all', reinforcing the negative.","jlpt":"N5"},{"jlpt":"N5","tip":"Use 'no' for things you can see, hear, or feel directly, like 'seeing' windows.","meaning":"Turns a verb into a noun phrase to make it the subject or object of a sentence.","example":"店の窓を見るのは楽しかったです。","pattern":"Dictionary Form + の/こと"},{"jlpt":"N4","tip":"Think of this as the 'Natural Law' or 'Button' IF. If you press the button (condition), the light turns on (result).","example":"夜になると、店の電気が明るくて...","meaning":"Expresses a natural consequence, a habit, or an inevitable result (whenever A happens, B follows).","pattern":"Dictionary Form + と"},{"tip":"The main action comes second. Here, 'being happy' is the state while 'walking' is the background action.","example":"私は町を歩きながら、とても幸せでした。","meaning":"Indicates that two actions are being performed simultaneously by the same person.","pattern":"Verb Stem + ながら","jlpt":"N4"},{"tip":"In this story, it emphasizes that the bad feelings disappeared completely and perhaps unexpectedly.","meaning":"Expresses the completion of an action, often with a sense of regret, surprise, or being finished unintentionally.","example":"あんなに暗くて嫌な気持ちが、たった一つのレモンで消えてしまったのです。","pattern":"Verb (Te-form) + しまう/しまった","jlpt":"N4"},{"pattern":"Verb Stem / Adjective Stem + すぎる","example":"重すぎず、軽すぎず、私の心にちょうどよかったです。","meaning":"Indicates that something is excessive or 'too much'. Using the negative 'sugizu' means 'not too...'.","tip":"For I-adjectives, remove the 'i'. For example, 'omoi' becomes 'omo-sugiru'.","jlpt":"N3"}],[{"meaning":"A and B (exhaustive list)","example":"丸善は、大きい本屋と文房具の店です。","tip":"Matches the English \"and\" perfectly for connecting nouns. Unlike 'ya', it implies these are the only items mentioned.","jlpt":"N5","pattern":"A と B"},{"example":"あの丸善に入ってみよう","tip":"Used when you want to sample an experience. In the volitional form 'miyō', it reflects a self-directed 'shall I' or 'let's'.","meaning":"To try doing something / To see what something is like","pattern":"～てみる (volitional: ～てみよう)","jlpt":"N4"},{"pattern":"～と、～","jlpt":"N4","example":"丸善にいると、息が苦しくなります。","tip":"When used at the end of a clause, 'to' indicates an inevitable result or a physical reaction to an environment.","meaning":"Whenever A happens, B naturally follows (condition)"},{"pattern":"～ふりをする","jlpt":"N3","meaning":"To pretend to; to act as if...","tip":"Usually used for intentional deception or acting. Use it with plain forms of verbs or nouns + no.","example":"知らないふりをして店を出たら、どうなるだろう"},{"tip":"This is the most versatile 'if' in Japanese. It focuses on what happens 'after' the condition is met.","example":"知らないふりをして店を出たら、どうなるだろう","meaning":"If/When (conditional)","pattern":"～たら","jlpt":"N3"},{"jlpt":"N3","pattern":"～（の）ようだ/ようです","tip":"Used to describe something by comparing it to something else. 'Noun + no yō' makes a simile.","example":"全部そのレモンの黄色に吸い込まれるようでした。","meaning":"It seems like; as if; looks like (simile/appearance)"},{"meaning":"After doing (sequence of events)","tip":"Emphasizes that event B cannot happen until event A is completed. Different from 'ato de' which just marks time order.","example":"私が店を出てから数分後に、ドカーンと大きい爆発をします。","jlpt":"N3","pattern":"～てから"}]],"intermediate":[[{"example":"お酒を毎日飲んでいると","pattern":"V-dictionary form + と","jlpt":"N4","tip":"This pattern is used for habitual actions or natural results that occur every time the condition is met.","meaning":"Whenever A happens, B follows; or if A happens, then B (natural consequence)."},{"example":"壊れかかった街だ","pattern":"V-stem + かける / かかった","jlpt":"N3","meaning":"To be in the middle of an action, or about to start something (often implying it didn't finish).","tip":"Use this for things that have started changing but haven't reached the final result yet, like 'dying' or 'eating (half-finished)'."},{"jlpt":"N3","pattern":"V-stem + 回る (まわる)","example":"京都の街から街へと歩き回っていた","tip":"It physicalizes the action to imply movement over a wide area, like 'running around' or 'looking around'.","meaning":"To do something all around or aimlessly."},{"example":"急に立ち上がって帰りたくなってしまう","pattern":"V-te form + しまう / しまった","jlpt":"N4","tip":"In this text, it emphasizes the narrator's lack of control over his sudden impulses.","meaning":"To end up doing something (often unintentionally or with regret)."},{"jlpt":"N4","pattern":"V-causative (せて/させて)","example":"何かが私をそこにじっとさせておかないのだ","meaning":"To make or let someone do something.","tip":"The text uses 'させておかない' meaning 'won't let/allow me to stay still'. Pay attention to the -nai ending."},{"jlpt":"N3","pattern":"～のだ / ～んだ","example":"自分の心の中の風景と似ていると感じたのだ","tip":"In literature, this often signals a shift from describing events to describing the narrator's inner thoughts or reasons.","meaning":"Used for emphasis or to provide an explanation or background for a situation."},{"jlpt":"N3","example":"どうしようもない重い気持ち","pattern":"～ようがない / ～ようもない","meaning":"It cannot be helped; there is no way to do it.","tip":"'Doushiyoumonai' is a very common set phrase meaning 'helpless' or 'hopeless'."}],[{"jlpt":"N5","pattern":"V(potential)","example":"何も買えなかった","tip":"In modern speech, 'ra-nuki' (dropping 'ra') is common for Ru-verbs (e.g., tabereru instead of taberareru).","meaning":"Potential form: indicates the ability to do something. For Ru-verbs, replace -ru with -rareru; for U-verbs, change the last vowel to -e and add -ru."},{"jlpt":"N4","pattern":"V(stem) + 続ける","tip":"This is a compound verb. Use it when an action persists over a period of time.","example":"歩き続けた","meaning":"To continue doing an action. (Verb stem + tsuzukeru)"},{"meaning":"To have a feeling/hunch that... or it feels like...","example":"元気が出てくるような気がした","tip":"Use this for subjective feelings or intuitions rather than objective facts.","jlpt":"N3","pattern":"～気がする"},{"pattern":"V(dictionary form) + ことで有名だ","jlpt":"N3","tip":"The 'koto' turns the verb into a noun phrase so it can be followed by the particle 'de'.","example":"果物を並べることで有名だった","meaning":"Known for / Famous for (doing) something."},{"meaning":"The moment that... / As soon as...","tip":"This emphasizes that the two actions happened almost simultaneously.","example":"レモンを買った瞬間から","jlpt":"N3","pattern":"V(plain past) + 瞬間（に）"},{"pattern":"V(te-form) + くる","jlpt":"N3","meaning":"An auxiliary used to describe a process that is beginning, or an action coming toward the speaker (physically or metaphorically).","tip":"In this context, it shows a change in the speaker's internal state (energy emerging).","example":"元気が出てくるような気がした"},{"meaning":"As if / Like. Used to describe something that appears to be something else or to make a comparison.","tip":"Unlike 'sou' (looks like), 'you na' is used for metaphors or when you are more certain of the resemblance.","example":"健康になったような錯覚に陥った","pattern":"～（かの）ような / ように","jlpt":"N3"},{"jlpt":"N2","pattern":"～なんて / とは","meaning":"Expresses surprise, disbelief, or emotional emphasis regarding a fact. Often used when the speaker is moved by something.","tip":"It functions like a exclamation point at the end of a thought, often implying \"I can't believe that...\"","example":"幸せになれるなんて"}],[{"example":"丸善に入っていった。","pattern":"～ていく (te-iku)","jlpt":"N4","meaning":"To go and do something / To continue a movement away from the speaker","tip":"Think of 'iku' (to go). It shows the action is moving away from your current location or moving forward into the future."},{"jlpt":"N3","tip":"Use this for sudden, unexpected changes that happen immediately after an action.","meaning":"Just as; the moment that...","example":"店に入った途端","pattern":"～た途端 (ta totan)"},{"jlpt":"N3","meaning":"Expected to be; should be (based on logic or general expectation)","tip":"Use 'hazu' when you have a strong reason to believe something is true, even if the reality is different.","example":"好きなはずの画集","pattern":"～はず (hazu)"},{"meaning":"Repetition of actions (A, then B, A, then B...)","tip":"This structure often describes a repetitive cycle of actions or events, like a person pacing back and forth.","jlpt":"N2","pattern":"～ては (te wa)","example":"本を引き出しては積み上げ"},{"example":"成し遂げたかのように","pattern":"～かのように (ka no you ni)","jlpt":"N3","tip":"This is used for metaphors. The speaker knows it's not literally true, but it feels that way.","meaning":"As if; just like..."},{"meaning":"Explanatory emphasis; giving a reason or clarifying a situation.","tip":"In literature, this often signals a moment of realization or a definitive explanation for an action.","jlpt":"N4","pattern":"～のだ / ～んだ (no da / n da)","example":"レモンを置いたのだ。"},{"example":"知らん顔をして外へ出たらどうなるだろう","pattern":"～たらどうなる (tara dou naru)","jlpt":"N4","tip":"This is the standard way to pose a hypothetical question or wonder about the consequences of an action.","meaning":"What if...; What would happen if...?"}]],"original":[[{"meaning":"Indicates a natural consequence, habit, or a certainty that follows an action. (When/If A, then B)","example":"酒を毎日飲んでいると...時期がやって来る。","pattern":"～と","jlpt":"N4","tip":"In this context, it describes a regular occurrence or an inevitable result. It is often used for facts and physical laws."},{"pattern":"～てしまう","jlpt":"N4","tip":"In literature, this often emphasizes the finality of the state or the speaker's emotional resolution.","example":"京都から逃げ出して誰一人知らないような市へ行ってしまいたかった。","meaning":"To do something completely, or to do something accidentally/regrettably."},{"meaning":"Used to list multiple examples or possibilities (like 'A and B', 'A or B').","pattern":"～とか～とか","tip":"Unlike 'ya', 'toka' is more casual and is frequently used when giving examples of locations or objects in a series.","jlpt":"N4","example":"京都から何百里も離れた仙台とか長崎とか..."},{"meaning":"An auxiliary verb indicating that a state resulting from some action remains or exists.","example":"汚い洗濯物が干してあったりがらくたが転がしてあったり...","pattern":"～てある","jlpt":"N4","tip":"Focuses on the state of the object rather than who performed the action. It implies someone did it for a purpose."},{"meaning":"Listing actions or states among others, implying that the list is not exhaustive.","example":"土塀が崩れていたり家並が傾きかかっていたり...","tip":"The final 'suru' can be omitted or changed to different forms like 'shiteiru' (ongoing state).","jlpt":"N4","pattern":"～たり～たりする"},{"meaning":"Indicates that an action or a state has started but is not yet finished, or is in the middle of happening.","pattern":"～（ます形）＋かける / かかっている","tip":"Use this for things that are midway through a process (e.g., 'half-eaten', 'starting to rot').","jlpt":"N3","example":"家並が傾きかかっていたり..."},{"jlpt":"N2","tip":"This carries a strong emotional nuance of 'looking back fondy' or 'reflecting' on how things were.","pattern":"～たものだ","example":"私は幼い時よくそれを口に入れては父母に叱られたものだが...","meaning":"Used to express a nostalgic habit or something that used to happen frequently in the past."}],[{"jlpt":"N4","pattern":"～てしまう (～てしまった)","tip":"In this context, it emphasizes the finality of the friend leaving, contributing to the narrator's feeling of emptiness.","meaning":"Expresses completion, often with a sense of regret or accidental occurrence.","example":"友達が学校へ出てしまったあと"},{"pattern":"(V-ba form) + (V-dictionary form) + ほど","jlpt":"N3","example":"奥へゆけばゆくほど堆高く積まれている。","meaning":"The more (A), the more (B). Used to describe a proportional increase.","tip":"The verb used must be the same in both parts of the pattern."},{"meaning":"Describes a situation that eventually reaches a certain (often extreme or formal) result or state.","example":"あんなにも私を誘惑するには至らなかったと思う。","tip":"It is a formal way to say 'come to' or 'arrive at' a result/conclusion.","pattern":"～に至る (～には至らなかった)","jlpt":"N2"},{"pattern":"(Verb/Adjective) + ほど","jlpt":"N3","meaning":"To the extent that... / So much so that... Provides a degree of scale for the description.","example":"思わせるほどなので","tip":"Use this when you want to use a specific situation as a yardstick for how intense a feeling or state is."},{"pattern":"～のような / ～のように","jlpt":"N4","meaning":"Used to describe something by comparing it to something else (simile/metaphor).","example":"あの檸檬が好きだ。レモンエロウの絵具をチューブから搾り出して固めたような...","tip":"A 'noun + の + ような' describes a noun, while 'noun + の + ように' describes a verb or adjective."},{"tip":"Unlike 'youni', 'tame ni' implies a clear intention or a direct benefit/reason.","example":"身体に熱が出た。事実友達の誰彼に私の熱を見せびらかすために...","meaning":"Indicates a purpose, goal, or reason for an action.","jlpt":"N4","pattern":"(Verb-dictionary / Noun + の) + ために"},{"tip":"Here it describes the physical sensation of coldness gradually spreading deep into the body.","meaning":"Indicates a movement away from the speaker’s current perspective or a continuous change into the future.","example":"掌から身内に浸み透ってゆくような...","jlpt":"N4","pattern":"～てゆく (～ていく)"},{"tip":"This is a literary expression often used with verbs of thinking (omoia-agumu) or searching (sagashi-agumu).","meaning":"To be tired of doing something, or to struggle with doing something for a long time without success.","example":"探しあぐんでいたもので","jlpt":"N1","pattern":"(V-stem) + あぐむ (あぐんでいた)"}],[{"jlpt":"N4","example":"歩き廻った疲労が出て来たのだと思った。","meaning":"Used to explain a reason, provide background information, or emphasize a discovery/conclusion.","tip":"In writing, 'noda' sounds more decisive or explanatory than the simple polite form.","pattern":"～のだ / ～んだ"},{"pattern":"～てみる","tip":"Combine it with 'wa' (te-wa-miru) to emphasize repeated, repetitive attempts.","meaning":"Implies trying to do something to see what the result is, often with a sense of uncertainty or futility in this context.","example":"画本を抜き出してはみる、そして開けてはみるのだが","jlpt":"N4"},{"jlpt":"N3","tip":"This expresses a strong psychological compulsion or a need to satisfy one's feelings.","meaning":"A phrase meaning 'cannot rest satisfied until...' or 'cannot feel at ease without doing...'","example":"一度バラバラとやってみなくては気が済まないのだ。","pattern":"～なくては気が済まない"},{"jlpt":"N3","example":"あまりに尋常な周囲を見廻すときのあの変にそぐわない気持を、私は以前には好んで味わっていたものであった。","meaning":"Used to recall a past habit or a state that used to exist (often with a sense of nostalgia).","tip":"It often translates to 'used to do' or 'would often do' in English.","pattern":"～たものであった / ～たものだ"},{"pattern":"～たら（どう）","jlpt":"N3","example":"一度この檸檬で試してみたら。","tip":"When the sentence ends with 'tara,' it often functions as a suggestion or a 'what if' scenario.","meaning":"A casual or internal monologue way of saying 'How about if...?' or 'Why don't I try...?' (shortened from -tara dou desu ka)."},{"jlpt":"N2","example":"城壁の頂きに恐る恐る檸檬を据えつけた。","meaning":"A compound verb structure where the first verb is in the -masu stem, meaning to finish/fix/attach something firmly or completely.","tip":"This suffix often adds a sense of 'firmness' or 'intensity' to the action.","pattern":"～つける (stem + つける)"},{"tip":"Pair 'donnani' with 'kana' or 'darou' to emphasize the degree of a hypothetical feeling.","meaning":"An exclamatory expression meaning 'How... it would be!' used to express strong emotion or imagination.","example":"大爆発をするのだったらどんなにおもしろいだろう。","jlpt":"N2","pattern":"どんなに ～だろう"}]]},"hana":{"simplified":[[{"example":"知らない人はいません","pattern":"～ない～はいない","jlpt":"N5","meaning":"Double negative (lit. \"there is no one who doesn't know\") used to emphasize that 'everyone' knows.","tip":"In Japanese, using two negatives often makes the statement stronger and more formal than a simple affirmative."},{"meaning":"Used to describe something by comparing it to something else (simile).","tip":"Use this when something resembles another thing in appearance or manner. Use 'no yō da' at the end of a sentence and 'no yō ni' before a verb or adjective.","pattern":"～のようだ / ～のように","example":"ソーセージのようです","jlpt":"N4"},{"jlpt":"N4","example":"鼻を短く見せる方法","pattern":"V-(さ)せる","tip":"In this context, 'miseru' (to show) is the causative of 'miru' (to see). It is used to describe an action that influences the appearance of something.","meaning":"The Causative form, used here to mean \"to make something look\" or \"to let something look.\""},{"tip":"This focuses on the person receiving the action. It implies gratitude or that the action was requested.","meaning":"To have someone do something for you; receiving a favor.","jlpt":"N4","pattern":"V-て もらう","example":"鼻を踏んでもらいます"},{"meaning":"The passive voice combined with 'te mo' (even if). Here it marks the subject's nose being affected by someone else's action.","tip":"The passive '踏まれる' (fumareru) is used here. In Japanese, the person whose body part is affected is usually the subject of the passive sentence.","pattern":"V-(ら)れる ＋ ～ても","example":"鼻を踏まれても、全然痛くありません","jlpt":"N3"},{"example":"やってみることにしました","pattern":"V-ことにする","jlpt":"N3","meaning":"Indicates a personal decision to carry out an action.","tip":"Contrast this with 'koto ni naru' (it has been decided by outside forces). 'Koto ni suru' emphasizes your own will."},{"meaning":"Used to provide an explanation, focus, or to emphasize a discovery/reason.","tip":"This 'no desu' pattern is very common in storytelling to add an explanatory tone to the facts being presented.","example":"鼻が元の長さに戻ったのです。","pattern":"～（ん）です / ～（の）だ","jlpt":"N3"},{"example":"笑うようになります","pattern":"V-る ＋ ようになる","jlpt":"N3","meaning":"Indicates a change in state or the start of a new habit/behavior.","tip":"Use this to describe a shift from one condition to another (e.g., from 'not laughing' to 'laughing')."}]],"intermediate":[[{"jlpt":"N5","pattern":"～がいる/いない","meaning":"Used to indicate existence or presence. Combining with a negative ('shiranai hito') creates a double negative: 'There is no one who doesn't know' (Everyone knows).","tip":"Use 'iru' for living things and 'aru' for inanimate objects. In this text, it emphasizes the monk's fame.","example":"知らない人はいない。"},{"example":"十五センチくらいあって","meaning":"Approximately or about. Used to show an estimated amount, time, or length.","tip":"'Gurai' sounds slightly more casual than 'kurai', but they are interchangeable in most contexts.","pattern":"～くらい / ぐらい","jlpt":"N5"},{"jlpt":"N4","example":"ソーセージのようなものが","tip":"Think of this as 'in the manner of' or 'having the appearance of'. It's essential for descriptive writing.","meaning":"Used to describe something by comparing it to something else (similitude). Like / as if.","pattern":"Noun + のような + Noun / Noun + のように + Verb/Adj"},{"jlpt":"N4","example":"鼻を気にしていると言われるのが恥ずかしい","pattern":"Verb (Passive Form) / ～れる・～られる","tip":"In Japanese, the passive is frequently used to express how someone's actions affect you emotionally (the 'suffering passive').","meaning":"Passive voice. Used when an action is performed upon the subject, often expressing annoyance or an objective fact."},{"example":"鼻をお粥の中に入れてしまったことがあり","tip":"In this story, it highlights the accidental and unfortunate nature of the monk's nose falling into the porridge.","meaning":"1. To do something completely. 2. To do something accidentally or with regret.","pattern":"Verb (Te-form) + しまう / しまった","jlpt":"N4"},{"jlpt":"N3","pattern":"少しも～ない / 全く～ない","tip":"This is a common 'pair' (so-o) expression. When you hear 'sukoshi mo', listen for the 'nai' at the end!","meaning":"(Not) at all / (Not) even a little. Used with a negative verb to emphasize complete negation.","example":"お坊さんになったことを少しも後悔していなかった。"},{"example":"鼻なんか気にしていないという態度をとって","pattern":"Noun + なんか / なんて","meaning":"Used to emphasize feelings of disdain, humility, or to dismiss something as unimportant. Similar to 'things like' or 'such a thing as'.","tip":"The monk uses 'nanka' to pretend his nose is a trivial matter, even though he is obsessed with it.","jlpt":"N3"},{"jlpt":"N2","example":"試そうとしなかった。","pattern":"Verb (Volitional) + と（は）しない","meaning":"To (not) try to do something, or to (not) make an effort to do something. Used with the volitional form.","tip":"Using the negative 'to shinai' indicates that the person has no intention of doing the action or shows a lack of effort."}]],"original":[[{"meaning":"Double negative used to emphasize that 'everyone' knows or does something.","jlpt":"N4","pattern":"～ない者はない / ～ない～はない","example":"池の尾で知らない者はない。","tip":"It functions as a strong 'Every' or 'Everyone' by saying 'There is no one who does not...'"},{"example":"鼻と云う語が出て来るのを何よりも惧れていた。","tip":"Commonly used for titles, names, or defining specific concepts. In literature, the kanji 云う is often used instead of 言う.","pattern":"～と云う (という)","jlpt":"N4","meaning":"Used to define or name something. 'The thing/word called...'"},{"jlpt":"N4","meaning":"Indicates that an action is done to the subject. In this context, it describes a story being 'spread' or 'rumored'.","example":"鼻を粥の中へ落した話は、当時京都まで喧伝された。","tip":"When the subject is an inanimate object or an event (like a story), the passive voice is often used to describe its state in society.","pattern":"～れる / ～られる（受身）"},{"jlpt":"N3","meaning":"Shows the speaker's conjecture or guess. '...probably / must be'.","tip":"Used when the speaker is making a guess based on evidence or common sense. Often used with 'why' (なぜ) or 'because' (から).","example":"あの鼻だから出家したのだろう。","pattern":"～だろう / ～でしょう"},{"jlpt":"N3","meaning":"Indicates that as one process progresses, another state changes in proportion. 'The more... the more...'.","pattern":"～ば～ほど","example":"苦心すればするほど、かえって長く見えるような気さえした。","tip":"The first verb is in the conditional 'ba' form, and the second is the dictionary form + hodo. It is used to show a direct correlation."},{"jlpt":"N2","meaning":"Used to express that the subject doesn't feel or think a certain way, even if others might expect them to.","pattern":"～とは思っていない / とは思わない","tip":"The 'wa' emphasizes the negation of that specific thought or feeling. It shows a clear internal stance.","example":"鼻に煩される事が少くなったと思っていない。"},{"jlpt":"N1","meaning":"An archaic/literary way to say 'As if' or 'Like'. equivalent to ~のようだ.","example":"有れども無きが如くである。","tip":"You will mostly see this in formal writing, literature, or set idiomatic phrases. In modern Japanese, use 'no you da'.","pattern":"～（が）如く (ごとく) / 如き (ごとき)"}]]},"matsu":{"simplified":[[{"pattern":"～ている","jlpt":"N5","example":"誰を待っているのか、自分でもわかりません。","tip":"Use this to describe what is happening right now or a habitual action.","meaning":"Indicating ongoing action or state (Present Continuous)"},{"tip":"The verb before 'ni' must be in its stem form (the part before -masu).","meaning":"Expressing the purpose of movement (going/coming to do something)","pattern":"Verb stem + に + 行く/来る","example":"迎えに行きます。/ 買い物に行きます。","jlpt":"N5"},{"pattern":"Verb stem + たい / たくない","jlpt":"N5","example":"買い物に行きたくありません。","tip":"Use 'tai' for your own desires. Change 'i' to 'kunai' for the negative form.","meaning":"Expressing desire (to want to do) / Negative (to not want to do)"},{"meaning":"Since/After doing (indicates a continuous state or action following an event)","tip":"Unlike just 'kara' (because), 'te-form + kara' specifically marks a sequence in time.","jlpt":"N4","example":"戦争が始まってから、毎日家で手伝いをしています。","pattern":"Verb (te-form) + から"},{"jlpt":"N3","example":"私は座ったまま、その人たちを見ています。","pattern":"Verb (ta-form) + まま","meaning":"Doing something while keeping a certain state unchanged","tip":"It often implies that the state is unusual or persists longer than expected."},{"meaning":"Nominalizing a verb (turning a verb into a noun)","tip":"Use 'no' for sensory verbs (see/hear) and 'koto' for ideas, facts, or habits.","jlpt":"N4","example":"電車が来るのをずっと待ちます。/ 待つことは、とても馬鹿なことかもしれません。","pattern":"Verb + の / こと"},{"pattern":"Verb (dictionary form) + ことしかできない","example":"私は待つことしかできません。","jlpt":"N4","meaning":"Nothing but/Only (emphasizes that there is no other option)","tip":"It is always followed by a negative verb, usually 'dekimasu' in the negative."},{"meaning":"To look like/To be like (similitude or appearance)","tip":"Use this when you are making a comparison based on appearance or how something feels.","pattern":"Noun/Verb + ような + Noun","example":"怒っているような顔です。","jlpt":"N3"}]],"intermediate":[[{"meaning":"Go to do something (movement with purpose)","jlpt":"N5","tip":"Replace 'masu' with 'ni iku'. It works with movement verbs like go, come, and return.","example":"人を迎えに行きます。","pattern":"Stem + に行く"},{"example":"電車が着くのを待ちます。","tip":"Use 'no' instead of 'koto' when describing something you directly perceive or physical actions like 'waiting'.","pattern":"Dictionary Form + の/こと","meaning":"Nominalizing a verb (turning a verb into a noun phrase)","jlpt":"N4"},{"meaning":"Every time (something happens)","jlpt":"N3","pattern":"Dictionary Form/Noun + たびに","example":"電車が着くたびに、たくさんの人が降りてきます。","tip":"Focus on the 'repetition' aspect. It emphasizes that every single time X happens, Y follows."},{"example":"ぼんやり座ったまま、その人たちを見ています。","tip":"Think of it as 'remaining in the state of...'. It often implies the state is slightly unusual for the following action.","pattern":"Short Past (Ta-form) + まま","jlpt":"N3","meaning":"To do something while leaving a state as it is (without change)"},{"meaning":"It doesn't mean that... / It's not the case that...","jlpt":"N3","pattern":"Plain Form + わけではない","example":"そんな、はっきりした人を待っているわけではありません。","tip":"Use this to gently deny an assumption or a logical conclusion rather than a simple fact."},{"example":"誰が何と言おうと、私は待つことしかできないのです。","tip":"This is a formal way to express 'no matter what'. The volitional form (iou, shiyou) is key here.","pattern":"Question word + Volitional Form + と","meaning":"No matter who/what... (Regardless of)","jlpt":"N2"},{"pattern":"Stem + 続ける","example":"待ち続けています。","tip":"This emphasizes the duration or the repetitive nature of an action over time.","meaning":"To continue doing something without stopping","jlpt":"N3"}]],"original":[[{"tip":"Used when the action involves or benefits another person you respect. \"Mairimasu\" is the humble version of \"Go/Come\".","jlpt":"N4","meaning":"Standard humble form to express the speaker's own actions politely.","example":"人をお迎えにまいります。","pattern":"お + Verb (stem) + になります/いたします/まいります"},{"tip":"With action verbs like 'sitting' or 'walking', it describes the current continuous state.","example":"私は、ぼんやり坐っています。","meaning":"Indicates an ongoing action or a current state.","jlpt":"N5","pattern":"～ている"},{"tip":"Emphasizes a repeated pattern or a recurring event.","jlpt":"N3","meaning":"Every time something happens; each time.","example":"電車がホームに到着するごとに","pattern":"Noun + の / Verb (dictionary form) + ごとに"},{"pattern":"～て/～で + たまらない","tip":"Used to express physical or emotional feelings that are so strong they are hard to control.","example":"世の中がいやでいやでたまらなくなります。","meaning":"Cannot help but...; extremely; unbearable.","jlpt":"N3"},{"example":"自分ほどの嘘つきが世界中にいないような","meaning":"To the extent of; as much as. (Used here to set a maximum level or standard).","jlpt":"N3","tip":"Used to express that \"nothing is more [adjective] than [noun]\".","pattern":"Noun + ほど + Negative / Affirmative"},{"pattern":"～かもしれない","tip":"A common way to express uncertainty or a guess about a situation.","jlpt":"N4","meaning":"Perhaps; maybe; indicates a possibility or conjecture.","example":"何かしら、よい機会をねらっているのかも知れない。"},{"pattern":"Verb (stem) + ぬ","example":"誰ともわからぬ人を迎えに。","meaning":"A formal or literary negative form, equivalent to ～ない.","jlpt":"N2","tip":"You will see this often in literature or old proverbs. It functions exactly like \"nai\"."},{"pattern":"Verb (stem) + たく + も + ない","tip":"Adding \"mo\" between the \"taku\" (desire) and \"nai\" (negative) adds strong emphasis to the feeling of reluctance.","jlpt":"N3","example":"言いたくもない挨拶を","meaning":"Emphasizes the negative desire; \"don't even want to...\"."}]]},"asa":{"simplified":[[{"example":"遊ぶことが一番好きです。","meaning":"Nominalizes a verb to turn an action into a 'thing' or 'activity'.","jlpt":"N5","tip":"Think of this as adding \"-ing\" to a verb to make it a subject or object (e.g., 'playing').","pattern":"V-dictionary form + こと"},{"meaning":"Indicates receiving a favor or having someone do something for you.","example":"家族にお弁当を作ってもらって","pattern":"V-te + もらう","tip":"Focus on who the giver is; they are marked with the particle 'ni'.","jlpt":"N4"},{"tip":"Pronounced 'toori'; it literally means 'following the path of' something.","pattern":"Noun + の + 通り(に) / V-form + 通り(に)","jlpt":"N3","meaning":"Doing something exactly as planned or as instructed.","example":"予定の通りに進みます。"},{"tip":"Use this for 'whenever' or constant results, like descriptions of nature or machines.","pattern":"V-plain / い-adj + と","jlpt":"N4","meaning":"Indicates a natural consequence or a predictable outcome (If A happens, B follows).","example":"午後3時ごろになると、疲れます。"},{"meaning":"Although I say [X], the reality is slightly different or more specific.","example":"仕事部屋と言っても、実はそこは若い女の人の部屋です。","tip":"Use this to clarify or qualify a statement that might lead to a misunderstanding.","pattern":"～と言っても","jlpt":"N3"},{"jlpt":"N5","tip":"Unlike nouns (which need 'no'), verbs always use the dictionary form even if the action happened in the past.","pattern":"V-dictionary form + 前に","example":"女の人が銀行から帰る前に","meaning":"Before doing an action."},{"meaning":"Expressing a plan or intention to do something.","example":"結婚する予定です。","pattern":"V-dictionary form + 予定です","tip":"Use this for concrete plans or schedules that have already been decided.","jlpt":"N4"}],[{"example":"歩くことができなくなりました","jlpt":"N5","tip":"It combines 'koto ga dekiru' (can do) and 'naru' (to become). It describes a change in ability.","meaning":"To become / to reach a state where something is no longer possible","pattern":"Dictionary Form + ことができなくなる"},{"tip":"Often used for situations that are slightly unusual, like sleeping with clothes or shoes on.","pattern":"Verb (Ta-form) + まま / Noun + のまま","meaning":"To do something while leaving a state as it is; 'left as is' or 'still'","jlpt":"N4","example":"コートを着たまま寝ました"},{"example":"電気をつけようとしました","jlpt":"N4","meaning":"To try to do something / to be about to do something","pattern":"Volitional Form + とした","tip":"This implies the attempt was made but perhaps not completed or interrupted."},{"jlpt":"N4","example":"キクちゃんは笑いながら","pattern":"Verb (Stem) + ながら","meaning":"To do an action while doing another action (simultaneous actions)","tip":"The main action comes after 'nagara'. In this text, 'bringing the glass' is the main action while 'laughing'."},{"jlpt":"N4","example":"ろうそくをつけてくれたら","tip":"This is the most versatile 'if' form. It’s often used for chronological sequences: 'Once A happens, then B'.","pattern":"Verb (Ta-form) + ら","meaning":"If/When; expresses a condition for a result or a request"},{"example":"悪いことをしてしまうかもしれません","jlpt":"N4","meaning":"Might / perhaps; expresses a possibility of something happening","pattern":"Short Form + かもしれない","tip":"Used when the speaker is unsure but thinks there is a chance something is true or will happen."},{"tip":"In this context, it shows a repeated habit or accumulated experience leading up to the present moment.","meaning":"To have been doing something up until now; a continuous action from the past","pattern":"Verb (Te-form) + きた","example":"私は今まで... 失敗を何百回もしてきました","jlpt":"N3"},{"pattern":"A か B かしないと","meaning":"Unless A or B happens; if A or B doesn't happen (then a negative result follows)","tip":"'Nai to' at the end of a sentence often implies 'otherwise something bad will happen'.","jlpt":"N3","example":"ろうそくの火が消える前に私が寝るか、お酒の酔いがなくなるかしないと"}]],"intermediate":[[{"jlpt":"N5","tip":"Use this when you want to treat an action like an object, such as when saying 'My hobby is...' or 'I like...'.","pattern":"Dictionary Form + こと","example":"遊ぶことが何よりも好きです。","meaning":"Turning a verb into a noun phrase (nominalization)."},{"pattern":"Dictionary Form + と","tip":"In this context, it describes a habitual sequence of events: 'Whenever the door opens...'","jlpt":"N4","meaning":"Hypothetical or natural consequence (When A happens, B follows).","example":"戸が開くと、嫌な顔をして文句を言うふりをしますが･･･"},{"tip":"Use the plain form of verbs or adjectives before 'furi'. For nouns, use 'Noun + no + furi'.","pattern":"Verb/Adjective/Noun + ふりをする","jlpt":"N3","meaning":"Pretending to do something; acting as if.","example":"嫌な顔をして文句を言うふりをしますが･･･"},{"meaning":"Even if; even though.","example":"仕事をしていても、遠くから友達が訪ねて来るのを･･･","tip":"This creates a contrast. Even though the speaker is working, they are actually waiting for friends.","pattern":"～て + も","jlpt":"N4"},{"meaning":"In the middle of doing; unfinished.","example":"書きかけの原稿をすぐに片付けて･･･","pattern":"Verb Stem + かけ","tip":"This is used for actions that have started but are not yet complete, like an unfinished book or half-eaten food.","jlpt":"N3"},{"example":"仕事部屋と言っても、実はそこは若い女の人の部屋なのです。","meaning":"Although one might say...; while it's called...","jlpt":"N2","tip":"Use this to clarify or qualify a statement that might lead to a misunderstanding. It provides a 'reality check' to the previous term.","pattern":"～と言っても"},{"pattern":"Verb Stem + そうな + Noun","tip":"When used with a verb stem, it indicates a likelihood or a typical behavior associated with that type of person.","jlpt":"N3","meaning":"Looks like; seems like; likely to.","example":"人生経験が豊かな大人が言いそうなことを書いて･･･"},{"jlpt":"N4","pattern":"～よう(だ/です)","tip":"This expresses a conjecture or appearance based on what the speaker has observed or sensed.","example":"彼女は、その青年とあっさりと結婚するつもりのようでした。","meaning":"It seems that; it looks like."}],[{"pattern":"～かもしれない","tip":"In casual speech, 'kamo' is often used alone at the end of a sentence.","jlpt":"N5","example":"吐いてしまうかもしれない","meaning":"Expresses a possibility that something might happen (50% chance or less).Often used for negative outcomes."},{"jlpt":"N4","pattern":"～てしまう/～ちゃう","tip":"In this text, 'yatte shimatta' (I've done it) is a classic expression of regret.","meaning":"Used to express completing an action fully, or to express regret/accidentally doing something.","example":"寝てしまいました"},{"pattern":"～そうにない / ～そうもない","tip":"This is the negative form of the 'appearance' -sou. Change the 'i' of an adjective or 'masu' of a verb to 'sou ni nai'.","jlpt":"N4","example":"歩いて帰れそうにない","meaning":"Indicates that something is unlikely to happen or seems impossible based on current signs."},{"example":"足袋を履いたまま寝ている","meaning":"Describes doing something while keeping a certain state or condition unchanged.","tip":"Often used for things that are usually changed, like sleeping with shoes 'mama' or clothes 'mama'.","pattern":"～まま","jlpt":"N4"},{"pattern":"～くらい / ～ぐらい","tip":"Use this when you want to emphasize how intense a situation is by comparing it to a specific action.","jlpt":"N3","example":"歩けないくらい酔っ払っていました","meaning":"Indicates the extent or degree of a state by providing an example. 'To the extent that...'"},{"example":"おしっこをしたものなんだよ","meaning":"Used to describe a common habit, social norm, or a general truth about the past. 'Used to do...'","tip":"When used with past tense verbs, it conveys nostalgia or describes frequent past behaviors.","pattern":"～（た）ものだ / もんだ","jlpt":"N3"},{"jlpt":"N2","tip":"This is a polite/formal equivalent of 'nai de sumu'. It often implies relief at avoiding a negative situation.","pattern":"～ずに済む","meaning":"To get by or manage without doing something. 'Zu' is a formal negative form.","example":"間違いを起こさずに済む"},{"meaning":"Used to emphasize that the reality is the opposite of or much more extreme than what was expected. 'Far from...'","example":"酔いが覚めるどころか、体が熱くなり...","jlpt":"N2","pattern":"～どころか","tip":"Focus on the contrast: 'A dokoro ka B' means not only is A not true, but the even more extreme B is the case."}]],"original":[[{"tip":"Compared to から, ので is more polite and objective, often used when explaining circumstances.","jlpt":"N5","example":"私は遊ぶ事が何よりも好きなので","meaning":"Used to link a reason or cause to an effect (since/because).","pattern":"～ので"},{"tip":"In literature, this often shows the speaker's social position or authority over the person performing the action.","jlpt":"N4","meaning":"The causative form indicates making or letting someone do an action.","pattern":"～させる (使役形)","example":"弁当を作らせ、それを持ってその仕事部屋に出勤する。"},{"jlpt":"N3","tip":"Adding 'も' emphasizes the contrast between the two halves of the sentence.","pattern":"～ながら（も）","meaning":"Expresses that two actions or states happen simultaneously, or indicates a contradiction (even though/while).","example":"家で仕事をしていながらも"},{"tip":"In dialogue, it often adds an explanatory or persuasive tone to the speaker's statement.","jlpt":"N3","meaning":"Used to explain a reason, provide background information, or emphasize a discovery.","pattern":"～のだ (んだ)","example":"あほらしく見えるんだからね。"},{"example":"結婚する気でいるようであった。","meaning":"Expresses an intention, state of mind, or feeling like doing something.","pattern":"～気でいる","tip":"It describes a continuous state of mind rather than a momentary decision.","jlpt":"N3"},{"example":"私には思われて来た。","pattern":"～（れ）てくる (自発)＋てくる","meaning":"The spontaneous form of a verb followed by 'to come to be'. It describes a thought or feeling that arises naturally.","jlpt":"N2","tip":"This combination is very common with sensory or mental verbs like 'think' (omou) or 'feel' (kanjiru) to show a gradual shift in perspective."},{"example":"ひとかどの苦労人の言いそうな事","pattern":"～そう（な/に）","meaning":"A suffix meaning 'appearing to be', 'looking like', or 'likely to'.","jlpt":"N2","tip":"When attached to a verb stem as a noun modifier (～そうな＋Noun), it describes the likely nature or behavior of that noun."}],[{"example":"大酒を飲むのは、毎夜の事であって、なにも珍らしい事ではない。","meaning":"Nominalizer used to turn a verb into a noun, often for making statements about that action.","tip":"Use this to define an action, like 'Working is fun' (働くのは楽しいです).","pattern":"～のは～だ","jlpt":"N5"},{"meaning":"Casual contraction of ～てしまう, indicating completion or a sense of regret/accidental action.","tip":"In casual speech, '～てしまう' becomes '～ちゃう' and '～でしまう' becomes '～じゃう' or '～じまう'.","jlpt":"N4","pattern":"～ちまう / ～ちゃう","example":"このままで、寝ちまうからね。"},{"example":"歩けないくらいに酔っていた。","tip":"It can describe a state so intense that it results in the action mentioned (e.g., 'so tired I can't walk').","meaning":"Indicates the extent or degree of a state; 'to the extent that...'","jlpt":"N3","pattern":"～くらい / ～ぐらい"},{"jlpt":"N3","pattern":"～そうもない","meaning":"Indicates that there is very little possibility of something happening. Emphasizes 'probably won't/can't'.","tip":"This is a stronger negative version of '～そうだ' (looks like). It is often used when you feel something is impossible.","example":"歩いて行けそうもないんだ。"},{"pattern":"～のに","jlpt":"N3","meaning":"Despite the fact that; even though. Expresses surprise, regret, or complaint.","tip":"Unlike 'but' (が), 'のに' carries an emotional undertone of unexpectedness or dissatisfaction.","example":"足袋をはいているままで寝ているのに気附いて..."},{"pattern":"～かける / ～かけの","jlpt":"N3","tip":"Commonly used for things like 'eating' (食べかけ) or 'drinking' (飲みかけ) to show they aren't finished yet.","meaning":"Indicates that an action or state has started but is not yet finished; 'in the middle of...'","example":"酒が苦痛になりかけて来た時に..."},{"pattern":"～ずにすむ","jlpt":"N2","meaning":"To get by without doing something; to manage to avoid an action.","tip":"This is the formal version of '～ないで済む'. Use it when you are relieved a certain task or problem was avoided.","example":"何事も仕出かさずにすむと思った。"},{"pattern":"～的 (てき)","jlpt":"N2","meaning":"Suffix that changes a noun into an -na adjective, meaning '-ish', '-like', or 'typical of'.","tip":"Commonly used to create abstract descriptors like 'scientific' (科学的) or 'efficient' (効率的).","example":"本来は貴族的な事なんだ。"}]]},"gyofukuki":{"simplified":[[{"example":"秋になると、木の葉が赤や黄色になって...","tip":"Think of it as the \"natural consequence\" conditional. It often follows seasons or directions.","pattern":"～と","jlpt":"N5","meaning":"Whenever A happens, B naturally or inevitably follows. Used for nature, machines, or habits."},{"jlpt":"N3","meaning":"From... through/to... (expressing a range in time or space with fuzzy boundaries).","tip":"Unlike 'kara... made', which marks a specific endpoint, 'kake-te' suggests a general area or duration.","example":"夏から秋にかけて、たくさんの人が遊びに来ます。","pattern":"～から～にかけて"},{"pattern":"V-stem + やすい","tip":"It is treated like an i-adjective. The opposite is '～にくい' (difficult to do).","example":"崖は水で滑りやすかったです。","meaning":"Easy to do or prone to doing something.","jlpt":"N4"},{"pattern":"V-stem + ながら","example":"お酒を飲みながら言いました。","tip":"The main action comes second. Here, the 'speaking' is the main focus, 'drinking' is the background action.","jlpt":"N5","meaning":"While doing A, also doing B. Shows two actions happening simultaneously by the same person."},{"meaning":"Whenever (every time) someone does X, Y always happens.","jlpt":"N3","pattern":"V-dictionary form + たびに","example":"滝を見るたびに、その蛇を考えました。","tip":"Use this to highlight a repeated coincidence or a consistent emotional reaction."},{"tip":"It describes an attempt or the moment just before an action starts. It often implies the action was unsuccessful.","example":"草を取ろうとしました。/ スワを捕まえようとしました。","pattern":"V-volitional + と（する/している）","jlpt":"N4","meaning":"To try to do or be about to do something."},{"example":"お父さんが言ったように、私は大きい蛇になった。","tip":"When used after a verb, it often means \"following the manner of\" or \"just as [someone] said/did.\"","pattern":"V-plain + ように","jlpt":"N3","meaning":"Like/as... (used to indicate that an action or state is similar to something else)."}]],"intermediate":[[{"jlpt":"N5","meaning":"Used to list two or more nouns non-exhaustively (meaning \"A and B, among others\").","example":"赤や黄色に色づいて","pattern":"～や～(など)","tip":"Unlike 「と」 which lists everything, 「や」 implies there are other things in the category not mentioned."},{"jlpt":"N4","example":"春が来るのをじっと待っていました。","meaning":"Turns a verb phrase into a noun clause, often used as the object of the sentence.","tip":"Use this when you want to describe an action as if it were a thing (e.g., 'the act of waiting').","pattern":"V-(辞書形)＋の"},{"jlpt":"N4","example":"滝を見るために集まり","meaning":"Indicates a purpose or reason (\"in order to\" or \"for the sake of\").","tip":"When following a verb, it always uses the dictionary form and indicates a conscious goal.","pattern":"V-(辞書形)＋ために"},{"jlpt":"N4","meaning":"Expresses the completion of an action, often with a sense of regret, accident, or unintentionality.","example":"足を滑らせて落ちてしまった","tip":"In spoken Japanese, this often contracts to 「ちゃった」 or 「じゃった」.","pattern":"～てしまう / ～てしまった"},{"jlpt":"N3","meaning":"Whenever/Every time (A) happens, (B) always happens as well.","example":"滝壺の水を見るたびに、蛇のことを想像していました。","tip":"Use this to highlight a repetitive connection between an action and a feeling or result.","pattern":"V-(辞書形) / Nの＋たびに"},{"tip":"Unlike 「から...まで」 which has a definite endpoint, 「にかけて」 is more approximate or spans the entire area/time.","pattern":"～から～にかけて","jlpt":"N3","example":"夏の終わりから秋にかけて","meaning":"Expresses a range through time or space, meaning \"from... through to...\" or \"over the period of...\"."},{"tip":"Pair this with results like 「～そうだ」 or 「～ということだ」 to report what you heard.","pattern":"～（が）言うには / ～によると","example":"父親が言うには、その蛇はもともと人間だったそうです。","meaning":"Used to indicate the source of information (\"According to...\") followed by hearsay.","jlpt":"N3"}]],"original":[[{"tip":"In casual speech, this becomes '～んだ'. Use it when you are explaining a situation rather than just stating a fact.","example":"ぼんじゅ山脈というのである。","meaning":"Used to explain reasons, provide background information, or add emphasis to a statement. In literature, it often gives a narrative, explanatory tone.","jlpt":"N5","pattern":"～のである / ～のだ"},{"pattern":"～さえ","tip":"When used with particles like 'ni' or 'de', it becomes 'ni sae' or 'de sae'. In negative sentences, it emphasizes a total lack of ability or result.","meaning":"Used to emphasize something by giving an extreme example, meaning 'even' or 'not even'.","example":"客を振りかえさすことさえ出来なかった。","jlpt":"N4"},{"pattern":"～と (conditional)","tip":"This specific 'to' is often used for giving directions or describing natural phenomena (e.g., 'Turn left and you will see...').","meaning":"Indicates that when one action or event occurs, another follows automatically or as a natural consequence.","example":"川を二里ばかりさかのぼると","jlpt":"N4"},{"pattern":"～から～にかけて","jlpt":"N3","meaning":"Indicates a general range of time or space, roughly meaning 'from... through...' or 'from... to...'. Not as precise as 'kara... made'.","example":"夏の末から秋にかけて","tip":"Use this when the boundaries of time or location are a bit fuzzy or continuous rather than a fixed point."},{"pattern":"～つつ (continuation)","example":"岩を噛みつつ流れ出ていた。","meaning":"Describes two actions happening simultaneously. It is more formal and literary than '～nagara'.","jlpt":"N2","tip":"It is often used in written descriptions to depict a continuous state or an ongoing motion."},{"pattern":"～（の）ではなくて～","meaning":"Used to correct a misconception by saying 'It's not A, but rather B'.","example":"飛び込んだのではなくて、まったくの過失からであった。","jlpt":"N2","tip":"This is a strong way to clarify a point or provide the true reason behind a situation."},{"jlpt":"N2","example":"足だまりにしていた頭ほどの石ころが","meaning":"Indicates extent or degree by comparison. In this context, it describes the physical size of the stone ('about the size of a head').","tip":"While 'hodo' can mean 'about' for numbers, using it after a noun like 'atama' (head) creates a vivid comparison of scale.","pattern":"～ほど (degree/extent)"}]]},"sakura":{"simplified":[[{"example":"死体が埋まっています","meaning":"Expresses a state that remains after an action has taken place (it is currently in a state of being buried).","jlpt":"N5","pattern":"～ている (State)","tip":"While it often means \"-ing\" for actions, for verbs like 'to bury' or 'to bloom', it describes the physical state of the object."},{"tip":"For adjectives, drop 'i' or 'na' before adding 'sugiru'. It implies that the excess is a problem or cause of concern.","pattern":"～すぎる","meaning":"Indicates that something is \"too much\" or excessive.","example":"桜がきれいすぎますから","jlpt":"N4"},{"tip":"It sounds softer than just 'kangaete' and invites the listener to explore an idea or experience.","pattern":"～てみる","jlpt":"N4","meaning":"To try doing something to see what it is like or what happens.","example":"考えてみてください"},{"tip":"If the result is negative, you should use 'sei de' (because of/fault of) instead.","pattern":"～おかげで","jlpt":"N3","meaning":"Thanks to... / used to express a positive result caused by something.","example":"この考えのおかげで"},{"tip":"Used here to give an example of the scale of the situation (so many insects you can't count them).","pattern":"～くらい / ～ぐらい","jlpt":"N3","meaning":"To the extent that... / so much so that...","example":"数えることができないくらい"},{"jlpt":"N3","meaning":"To make someone (feel/do) something. This is the Causative form.","example":"私を喜ばせません","tip":"Emotions + 'saseru' (like 'yorokobaseru') means to cause that emotion in someone else.","pattern":"～（さ）せる"},{"example":"飲むことができそうです","meaning":"It looks like / seems like (often based on current appearance or feeling).","jlpt":"N3","pattern":"～そうだ (Appearance)","tip":"When added to a verb's 'masu' stem, it means 'it looks like it will happen' or 'it seems possible'."}]],"intermediate":[[{"pattern":"～ている (Resultative state)","tip":"When used with intransitive verbs like 'umaru' (to be buried), it describes the current state resulting from a past action.","meaning":"Expresses a continuing state (something happened and the result remains).","example":"死体が埋まっている！","jlpt":"N5"},{"tip":"In casual speech, 'ii' can be followed by 'yo' for emphasis or 'da yo' as seen here.","example":"信じてもいいことなんだよ。","jlpt":"N5","meaning":"Used to grant permission or state that something is acceptable.","pattern":"～てもいい"},{"pattern":"～なんて","tip":"It is a more casual version of 'nado' or 'to iu no wa' and often carries a nuance of 'to think that...' or 'something like...'","meaning":"Used to express surprise, disbelief, or emotional emphasis regarding a topic.","example":"桜の花があんなにも見事に咲くなんて","jlpt":"N3"},{"tip":"Using the stem form (nari) instead of 'te' form (natte) makes the writing feel more literary and rhythmic.","meaning":"Joining sentences using the stem of a Masu-form verb instead of the 'te' form. Common in written or formal style.","example":"俺は反対に不安になり、憂鬱になり...","jlpt":"N3","pattern":"動詞の連用形 (Stem form for connecting)"},{"tip":"Always look for 'marude' at the start of the clause to anticipate the 'youni' or 'da' at the end.","meaning":"Used to describe something by comparing it to something else; 'just like' or 'as if'.","example":"まるで透視したように頭に浮かんでくる","jlpt":"N3","pattern":"まるで～ように"},{"meaning":"Used to indicate a reason or cause that leads to a negative or undesirable result.","example":"綺麗すぎるせいで","jlpt":"N3","tip":"Contrast this with 'okade' (thanks to), which is used for positive results. 'Sei' literally means 'fault'.","pattern":"～せいで"},{"pattern":"～気がする","meaning":"Expresses a feeling, hunch, or intuition that something might be true or might happen.","example":"酒が飲めそうな気がするよ。","jlpt":"N3","tip":"It's a very common way to express subjective feelings or vague certainties in Japanese."}]],"original":[[{"example":"屍体が埋まっている！","jlpt":"N5","meaning":"Indicates a continuing state or an ongoing action. In this context, it describes the state of the corpses being buried.","tip":"When used with intransitive verbs like 'umaru' (to be buried), it describes a resulting state that continues.","pattern":"～ている"},{"pattern":"～じゃないか","meaning":"A casual way to seek agreement or confirm something the listener should also know; 'isn't it?' or 'don't you agree?'","tip":"In literature, it can also be used as a self-rhetorical device to emphasize the speaker's conviction.","jlpt":"N4","example":"何故って、桜の花があんなにも見事に咲くなんて信じられないことじゃないか。"},{"pattern":"～にちがいない","tip":"Use this when you have a logical reason for your conclusion, even if it's based on subjective belief.","meaning":"Used to express a strong certainty or conviction that something is true; 'must be' or 'no doubt.'","jlpt":"N3","example":"同じようなことにちがいない。"},{"example":"～を想像してみるがいい。","meaning":"A slightly commanding or haughty way to say 'it is fine/good to do...' or 'you might as well...'","tip":"When used as 'V-te miru ga ii,' it sounds like a challenge or a suggestion from someone in a superior or more knowledgeable position.","jlpt":"N2","pattern":"～がいい/～ばいい"},{"example":"人の心を撲たずにはおかない。","jlpt":"N1","meaning":"Indicates that something will inevitably happen or that someone cannot help but do something; 'cannot help but...' or 'will certainly...'","tip":"This is a formal expression often used to describe natural results or strong emotional reactions that are impossible to suppress.","pattern":"～ずにはおかない"},{"example":"どんなに頭を振っても離れてゆこうとはしない。","pattern":"～（よ）うとはしない/～（よ）うともしない","tip":"The volitional form + 'to wa shinai' emphasizes a persistent resistance to a certain action or change.","meaning":"Used to say that something shows no sign of happening or that something (often inanimate) stubbornly refuses to change state.","jlpt":"N1"}]]},"urashima":{"simplified":[[{"example":"海へ行って魚をとり","jlpt":"N5","tip":"Think of it as 'Action A and then Action B'. It is the most fundamental way to chain actions in Japanese.","pattern":"～て (Te-form)","meaning":"Used to connect two or more verbs to describe a sequence of actions ('and then')."},{"example":"弱い動物をいじめてはいけません","jlpt":"N4","pattern":"～てはいけません","tip":"In casual speech, '～ては' often contracts to '～ちゃ', so this becomes '～ちゃだめ'.","meaning":"Used to express a strong prohibition or 'must not' do something."},{"pattern":"～てやる","tip":"Be careful! Using this with equals or superiors is rude; use '～てあげる' or '～てさしあげる' instead.","meaning":"To do something for someone (usually of lower status, children, or animals).","example":"亀を海へ帰してやりました。","jlpt":"N4"},{"example":"早く帰らなければなりません。","jlpt":"N4","tip":"Literally it means 'if you don't do it, it won't become (good).' In daily life, this is often shortened to '～なきゃ'.","pattern":"～なければなりません","meaning":"Used to express obligation or something that 'must' be done."},{"jlpt":"N4","example":"海のそばを歩いていると","meaning":"Used to describe a condition that leads to an unexpected discovery or natural consequence.","tip":"This 'to' emphasizes that Action B happened immediately and automatically after Action A.","pattern":"～と (conditional)"},{"example":"亀はとても苦しそうでした。","jlpt":"N3","tip":"For i-adjectives, drop the final 'i' (e.g., oishii → oishisou). For na-adjectives, just add 'sou'.","pattern":"～そう (appearance)","meaning":"Indicates that something 'looks like' or 'seems like' a certain state based on appearance."},{"example":"顔もしわだらけになりました。","jlpt":"N3","pattern":"～だらけ","tip":"It almost always has a negative connotation. You use it for 'covered in mud' but not 'covered in flowers'.","meaning":"Used to describe something covered in something unpleasant (dust, blood, wrinkles, etc.)."},{"pattern":"～ながら","tip":"The main action comes second. 'Naki-nagara mite ita' means the looking was the main action while crying.","meaning":"Indicates that two actions are being performed simultaneously by the same person.","example":"海のそばで泣きながら","jlpt":"N4"}]],"intermediate":[[{"tip":"Essential for introducing yourself or a specific title, e.g., 「[Name]という人」.","example":"浦島太郎という若い漁師","jlpt":"N5","meaning":"used to state the name of a person or thing (called \"...\")","pattern":"～という"},{"jlpt":"N4","example":"子供たちに捕まっていました","meaning":"passive form used to show someone is affected by an action (usually negative)","tip":"In Japanese, the passive voice is often used to express that the subject is inconvenienced or troubled by someone else's actions.","pattern":"～てしまう / 受身形 (Passive)"},{"pattern":"～てはいけない","tip":"Used for rules or moral prohibitions. In casual speech, it often shortens to ～ちゃいけない.","meaning":"expresses a strong prohibition (must not/should not)","jlpt":"N4","example":"そんなひどいことをしてはいけないよ"},{"pattern":"～かのように / ～かのような","tip":"Used when something isn't true but looks or feels very much like it is. ように behaves like an adverb.","example":"お礼を言っているかのように","jlpt":"N3","meaning":"as if; just like (metaphorical comparison)"},{"example":"好奇心に駆られました","jlpt":"N2","meaning":"to be overcome/driven by an emotion or impulse","tip":"Usually used with strong emotions like 'curiosity' (好奇心), 'anxiety' (不安), or 'impulse' (衝動).","pattern":"～に駆られる (にかられる)"},{"tip":"Attach to the verb stem. 「信じきれない」 means \"can't believe it at all/fully.\"","example":"表現しきれないほど素晴らしい","jlpt":"N2","meaning":"to do something completely/to the end; often used in the negative to mean \"cannot possibly finish\"","pattern":"～きる / ～きれない"}]],"original":[[{"jlpt":"N5","tip":"Use this when introducing someone or something the listener might not know yet.","pattern":"～という","example":"浦島太郎というりょうし","meaning":"called; named (Used to introduce a specific name)"},{"tip":"Always end the sequence with a form of 'suru'. It implies these are just examples of many possible actions.","jlpt":"N4","pattern":"～たり ～たりする","example":"石でたたいたり、さんざんにいじめているのです。","meaning":"to do things like... (listing multiple actions)"},{"example":"きき入れようともしないで","meaning":"without even trying to; showing no intention to...","pattern":"Volitional + と(も)しない","tip":"This describes someone else's lack of effort or refusal to do something.","jlpt":"N3"},{"jlpt":"N4","tip":"Use 'nara' when providing a suggestion or condition based on what the other person just said.","example":"おあしをくれるならやってもいい","meaning":"if; in the case that (conditional)","pattern":"～なら"},{"meaning":"there is no need to; it is unnecessary to...","example":"わざわざ礼なんぞいいにくるにはおよばないのに","pattern":"～には及ばない (にはおよばない)","tip":"In modern Japanese, it is often used for politeness ('no need to thank me') or to say competition is unnecessary.","jlpt":"N2"},{"tip":"In Japanese, the passive is often used to describe things happening to the protagonist as if they are being swept along by circumstances.","jlpt":"N4","example":"ただもう夢のようにはこばれて行きますと","meaning":"Passive voice (was carried)","pattern":"～られる (受身)"},{"jlpt":"N2","tip":"Unlike 'ya' or 'tari', 'dano' can sometimes sound like the speaker is complaining or overwhelmed by the variety.","pattern":"～だの ～だの","meaning":"things like... and... (often implies a messy or overwhelming list)","example":"かつおだの、ふぐだの、えびだの..."}]]}};

/** All grammar notes for a book+difficulty, flattened across all parts. */
export function getGrammarFlat(bookId: string, difficulty: string): GrammarNote[] {
  const v = bookGrammar[bookId]?.[difficulty];
  if (!v) return [];
  return v.flat();
}

/** Grammar notes for a specific part index (0-based). Falls back to flat for single-part books. */
export function getGrammarForPart(bookId: string, difficulty: string, partIndex: number): GrammarNote[] {
  const v = bookGrammar[bookId]?.[difficulty];
  if (!v) return [];
  if (v.length <= 1) return v[0] ?? [];
  return v[partIndex] ?? [];
}
